/* Plugin-level test through mpc-vst-plugins' real VST2 wrapper (run by tests/run_tests.sh under ASan/UBSan):
 * a cell tap, the cell's note label, save/restore into a second instance, and the playhead and readout following
 * the host transport. The generic tools/test_port.sh skips chunk restore for a port without continuous params. */
#include "engine.h"
#include "gen.h"   /* 0.18: old_state's chord rhythm */
#include "params.h"
#include "keyflags.h"   /* 0.19.1: generated by vst/make_skin.py */
#include "bassline.h"   /* 0.20: the tension words (the PHRASE centre) */
#include "melody.h"   /* 0.20: the classic Melody's recipe defaults (old_state, old_init_state) */
#include "jamlib.h"   /* 0.22: the JAM block names */
#include "presets.h"   /* 0.23: the genre presets' names */
#include "rhythm.h"   /* 0.18: the library rhythms' pictures */
#include "seq_core.h"   /* 0.12: the auditions test captures an engine's MIDI (seq_t.emit) */
#include "theory.h"
#include "voicing.h"   /* 0.17: the style table (the VOICING field fits) */
#include <math.h>
#include <stdarg.h>
#include <stdint.h>
#include <stdio.h>
