#include <string.h>

_Static_assert(KEYFLAGS_NPARAMS == NPARAMS, "keyflags.h is stale: run vst/build.sh");   /* 0.19.1 made for this params.h */

#ifndef SCREEN_BUDGET   /* screen updates per second while playing; tests/run_tests.sh passes it from vst/budget.json */
#error "build with -DSCREEN_BUDGET=<updates per second>"
#endif

typedef struct AEffect AEffect;
typedef intptr_t (*cb)(AEffect *, int32_t, int32_t, intptr_t, void *, float);
struct AEffect {
    int32_t magic;
    cb d;
    void *p;
    void (*setP)(AEffect *, int32_t, float);
    float (*getP)(AEffect *, int32_t);
    int32_t np, npar, ni, no, flags;
    intptr_t r1, r2;
    int32_t a, b, c;
    float io;
    void *obj, *user;
    int32_t uid, ver;
    void (*pr)(AEffect *, float **, float **, int32_t);
    void *pdr;
    char f[56];
};
extern AEffect *VSTPluginMain(cb);

enum { effClose = 1, effGetParamDisplay = 7, effGetParamName = 8, effGetChunk = 23, effSetChunk = 24 };
enum { audioMasterAutomate = 0, audioMasterGetTime = 7, audioMasterUpdateDisplay = 42 };
enum { kPlaying = 1 << 1, kPpqValid = 1 << 9, kTempoValid = 1 << 10 };

static double ti[16];   /* VstTimeInfo: [3] ppqPos, [4] tempo; flags at ((int32_t *)&ti[8])[5] */
static int32_t ti_flags = kTempoValid;
static double bpm = 120.0;
static long pushes;    /* screen updates sent to the host: audioMasterAutomate + audioMasterUpdateDisplay */
static long automated[NPARAMS];   /* audioMasterAutomate per param: what the wrapper reported to the host */
static float reported[NPARAMS];   /* 0.18: the value it reported last */
static long redraws;   /* 0.18: audioMasterUpdateDisplay alone (MPC then reads names and texts again) */
static int fails;

#define CHECK(c, ...) do { printf("%s ", (c) ? "ok  " : "FAIL"); printf(__VA_ARGS__); printf("\n"); if (!(c)) fails++; } while (0)
#define DOT " \xC2\xB7 "   /* 0.13: the cards' separator */
#define DIM "\xC2\xB0"     /* 0.13: theory.h's THEORY_DIM */

static intptr_t host(AEffect *e, int32_t op, int32_t i, intptr_t v, void *p, float o) {
    (void)e; (void)i; (void)v; (void)p; (void)o;
    if (op == audioMasterAutomate || op == audioMasterUpdateDisplay) pushes++;
    if (op == audioMasterAutomate && i >= 0 && i < NPARAMS) automated[i]++, reported[i] = o;
    if (op == audioMasterUpdateDisplay) redraws++;
    if (op == audioMasterGetTime) {
        ti[1] = 44100.0;
        ti[4] = bpm;
        ((int32_t *)&ti[8])[5] = ti_flags;
        return (intptr_t)ti;
    }
    return 0;
}

static int idx(const char *key) {
    for (int i = 0; i < NPARAMS; i++)
        if (!strcmp(PARAMS[i].key, key)) return i;
    return -1;
}

static void display(AEffect *a, const char *key, char *buf) {
    buf[0] = 0;
    a->d(a, effGetParamDisplay, idx(key), 0, buf, 0);
}

static void run(AEffect *a, int blocks, int playing) {
    float L[128], R[128], *o[2] = {L, R};
    for (int k = 0; k < blocks; k++) {
        ti_flags = kTempoValid | (playing ? kPlaying | kPpqValid : 0);
        a->pr(a, NULL, o, 128);
        if (playing) ti[3] += 128 * bpm / 60.0 / 44100.0;
    }
}

/* One lane's bar-on-view grid as "on/off label" text per step: what a cell shows and whether it is lit */
static void lane_cells(AEffect *e, int lane, char out[16][12]) {
    char key[16], lab[64];
    for (int st = 1; st <= 16; st++) {
        snprintf(key, sizeof key, "l%d_%d", lane, st);
        display(e, key, lab);
        snprintf(out[st - 1], 12, "%d%s", e->getP(e, idx(key)) > 0.5f, lab);
    }
}

static int same_cells(char x[16][12], char y[16][12]) {
    for (int i = 0; i < 16; i++)
        if (strcmp(x[i], y[i])) return 0;
    return 1;
}

static void press(AEffect *e, const char *key) {   /* a momentary: press, let the wrapper hold it, release */
    e->setP(e, idx(key), 1.0f);
    run(e, 2, 0);
    e->setP(e, idx(key), 0.0f);
}

/* A tap on a list cell (MPC sends the cell's new state: 1 on an unlit cell, 0 on the lit one), then a poll, so the wrapper's
 * echo guard knows the cell's state before the next tap. 0.17: an unpolled cell (IDEAS and SHAPE's, off the CHORDS page) is
 * never corrected by a poll, so MPC's toggle sends the other value at each tap after the first, as here */
static int is_button(const char *key);
static void tap(AEffect *e, const char *key, int v) {
    static signed char sent[NPARAMS];   /* an unpolled cell's last value + 1 on instance `who`, 0 none yet */
    static intptr_t who[NPARAMS], made;
    int i = idx(key);
    if (!e->user) e->user = (void *)++made;   /* the host's own field (calloc'd 0): tells a new instance from a freed one's address */
    if (who[i] != (intptr_t)e->user) who[i] = (intptr_t)e->user, sent[i] = 0;
    if (v && is_button(key)) {   /* 0.18: an image button's touch is a press (1) and a release (0): it latches in between */
        e->setP(e, i, 1.0f);
        run(e, 8, 0);
        e->setP(e, i, 0.0f);
        run(e, 8, 0);
        sent[i] = 1;
        return;
    }
    if (PARAMS[i].no_poll && sent[i]) v = sent[i] == 1;
    if (PARAMS[i].no_poll) sent[i] = (signed char)(v ? 2 : 1);
    e->setP(e, i, v ? 1.0f : 0.0f);
    run(e, 8, 0);
}

static int lit(AEffect *e, const char *key) { return e->getP(e, idx(key)) > 0.5f; }

/* 0.18 the image-button cells that latch (src/engine.c TAPB masks) */
static int is_button(const char *key) {
    static const char *const B[] = {"cpr_1", "cpr_2", "cpr_3", "cvo_1", "cvo_2", "cvo_3", "usy_1", "usy_2", "usy_3",   /* 0.19 usy_ as cvo_;
                                                                                         * 0.24.1 the RHYTHM pages' rac_ rfl_ rcx_ (y...) retired */
                                    "unk_1", "unk_2", "unk_3", "unk_4", "unk_5", "unk_6", "unk_7", "unk_8", "unk_9", "unk_10", "unk_11",
                                    "unk_12",   /* Task 9 fix: the bar editor's piano keys */
                                    "wsw_1", "wsw_2", "wsw_3", "wnk_1", "wnk_2", "wnk_3", "wnk_4", "wnk_5", "wnk_6", "wnk_7", "wnk_8",
                                    "wnk_9", "wnk_10", "wnk_11", "wnk_12",   /* 0.20 ANSWER PLAYS (as usy_) and the editor's piano (as unk_) */
                                    "cqf_1", "cqf_2", "cqf_3", "cqx_3", "cqx_4", "cqx_5", "cqx_6", "uqx_3", "uqx_4", "uqx_5", "uqx_6",
                                    "uqf_1", "uqf_2", "uqf_3", "uqk_1", "uqk_2", "uqk_3", "uqk_4", "uqk_5", "uqk_6",
                                    "uqk_7", "uqk_8", "uqk_9", "uqk_10", "uqk_11", "uqk_12"};   /* 0.24 PHRASE's RHYTHM fields, the BASS piano; 0.24.1 COPY TO...'s buttons */
    for (size_t i = 0; i < sizeof B / sizeof B[0]; i++)
        if (!strcmp(key, B[i])) return 1;
    return 0;
}
static void touch(AEffect *e, const char *key) { tap(e, key, !lit(e, key)); }   /* 0.18: a tap as MPC sends it (0 on a lit cell) */

/* 0.18: a touch on an image button (layout.conf "button": PROGRESSION's and VOICING's arrows and fields, the black keys, the cst_
 * hit plates, rfl_1..3, rac_3..6, rcx_4) as MPC sends it: two sets, the second undoing the first. The generated TUI.json gives the
 * button's component "Mouse Down" -> "Toggle Switch" on its param (as a list row's) and a Button sub on the same param that nothing
 * covers (a group of one, gestureBehaviour Instant). On a list row the Value label lies over the Button and takes the touch, so only
 * the row's Toggle Switch flips the value; a stepper arrow is a bare Button and its touch alone sets its param (toolchain
 * tools/shadow_skin.py). So a button's touch flips the value twice, both on the press. Seen on the Force (0.18.0): every touch on
 * LOCK locked the bar and unlocked it again. MPC holds what the wrapper last reported (lit, after the poll in run) */
static void button_tap(AEffect *e, const char *key) {
    int i = idx(key), held = lit(e, key);
    e->setP(e, i, held ? 0.0f : 1.0f);
    e->setP(e, i, held ? 1.0f : 0.0f);
    run(e, 8, 0);
}

/* 0.18 (device tap log): a touch on an image button as the Force sends it. The press sets 1; `hold` blocks later the release's
 * toggle flips the value MPC holds: the press's 1, or what the wrapper reported since (the poll's 0 for an unlit cell, which made
 * the release send 1 again: the device bug). With the latch the cell stays lit, nothing is reported and the release sends 0.
 * Returns how many values the wrapper reported to MPC during the hold */
static long device_press(AEffect *e, const char *key, int hold) {
    int i = idx(key);
    e->setP(e, i, 1.0f);
    long before = automated[i];
    run(e, hold, 0);
    long pushed = automated[i] - before;
    e->setP(e, i, (pushed ? reported[i] : 1.0f) > 0.5f ? 0.0f : 1.0f);
    run(e, 8, 0);
    return pushed;
}

/* 0.18 a press and its release on the engine itself (an image button cell latches on the 1 until the 0) */
static void en_press(const mpc_engine_t *en, void *x, const char *key) {
    en->set_param(x, key, "1");
    en->set_param(x, key, "0");
}

/* A 0..100 knob's value as the wrapper reports it (0.13: a dynamic_display knob's display is the engine's text) */
static void number(AEffect *a, const char *key, char *buf) { snprintf(buf, 16, "%ld", lroundf(a->getP(a, idx(key)) * 100)); }

static void no_emit(void *ctx, int status, int note, int vel, int frame) { (void)ctx; (void)status; (void)note; (void)vel; (void)frame; }

/* An instance with the pre-0.15 start (E minor 1-6-3-7, Chords Pulse, Bass Root, a classic Hook), loaded as a project
 * saved untouched, then run past the load guard: the tests written for that start. 0.15 instances start at INIT. (0.19: the load
 * converts its Bass lane; old_start puts it back, old_bass_on) */
static const char *old_state(void) {
    static seq_t q;
    static char st[SEQ_STATE_MAX];
    if (!*st) {
        seq_init(&q, no_emit, NULL);
        q.part[0].lane[LANE_CHORDS].gen = (seq_gen_t){GEN_CH_PULSE, 1, 30, 0};   /* 0.18: 0.17's generated Chords lane, which the load
                                                                                   * converts to drawn bars (Task 6) */
        seq_set_complexity(&q, LANE_CHORDS, 31);
        seq_set_complexity(&q, LANE_CHORDS, 30);   /* regenerates */
        q.part[0].lane[LANE_BASS].gen = (seq_gen_t){GEN_BASS_ROOT, 1, 31, 0};   /* 0.19: 0.18's generated Bass lane (Root c30) */
        seq_set_complexity(&q, LANE_BASS, 30);
        memset(&q.part[0].mel, 0, sizeof q.part[0].mel);   /* 0.20: 0.19's classic Hook (c30), not the JAM lane a new instance has */
        mel_defaults(MEL_HOOK, &q.part[0].mel, NULL);
        q.part[0].lane[LANE_MEL_UP].gen = (seq_gen_t){GEN_MEL_HOOK, 1, 31, 0};
        seq_set_complexity(&q, LANE_MEL_UP, 30);
        if (seq_state_save(&q, st, sizeof st) <= 0) st[0] = 0;
    }
    return st;
}

/* 0.19: INIT with 0.18's Bass lane (Root at COMPLEXITY 0, one root a bar), as a project saved untouched: the tests of the Bass
 * FIX written for INIT (a new instance's Bass is DRAWN; the load converts it, so its user puts it back, old_bass_on) */
static const char *old_init_state(void) {
    static seq_t q;
    static char st[SEQ_STATE_MAX];
    if (!*st) {
        seq_init(&q, no_emit, NULL);
        seq_init_preset(&q);
        q.part[0].lane[LANE_BASS].gen = (seq_gen_t){GEN_BASS_ROOT, 1, 1, 0};
        seq_set_complexity(&q, LANE_BASS, 0);   /* regenerates */
        mel_defaults(MEL_ARP, &q.part[0].mel, NULL);   /* 0.20: 0.19's INIT Melody, the Up-down Arp recipe (c30), not JAM */
        q.part[0].mel.opt[0] = 2;
        q.part[0].lane[LANE_MEL_UP].gen = (seq_gen_t){GEN_MEL_RECIPE, 1, 31, 0};
        seq_set_complexity(&q, LANE_MEL_UP, 30);
        if (seq_state_save(&q, st, sizeof st) <= 0) st[0] = 0;
    }
    return st;
}

static AEffect *start_from(const char *st) {
    AEffect *e = VSTPluginMain(host);
    if (e && *st) e->d(e, effSetChunk, 0, (intptr_t)strlen(st) + 1, (void *)st, 0);
    if (e) run(e, 70, 0);
    return e;
}

/* 0.19 (Task 6): a load converts a 0.18 Bass lane to DRAWN bars, so the tests written for the generated Bass (its FIX, IDEAS, SHAPE
 * and moves) put it back in the engine instance x after the load, as test_core's old_bass does: Root at COMPLEXITY cx, seed 1,
 * generated, no undo step; the host re-reads every value, as after a load */
static void old_bass_on(void *x, int cx) {
    seq_t *q = x;
    q->part[q->cur_part].lane[LANE_BASS].gen = (seq_gen_t){GEN_BASS_ROOT, 1, cx + 1, 0};
    seq_set_complexity(q, LANE_BASS, cx);   /* regenerates */
    q->display_rev++;
}

/* The engine instance behind a wrapped AEffect: the wrapper's per-instance state (vst2_wrap.c wrap_t) starts with the AEffect, the
 * host callback and the engine instance, mirrored here as AEffect is */
static void *engine_of(AEffect *e) {
    struct { AEffect fx; cb master; void *dsp; } *w = e->obj;
    return w->dsp;
}

/* 0.20: a new instance's Melody lane is JAM, which the retired MELODY pages and knobs (RECIPE, mrng..mgat, k_m...) leave; their
 * tests put back 0.19's INIT Melody in engine instance x: the Up-down Arp recipe at COMPLEXITY 30 (no undo step); the host
 * re-reads every value */
static void old_mel_on(void *x) {
    seq_t *q = x;
    seq_part_t *p = &q->part[q->cur_part];
    mel_defaults(MEL_ARP, &p->mel, NULL);
    p->mel.opt[0] = 2;   /* Up-down */
    p->lane[LANE_MEL_UP].gen = (seq_gen_t){GEN_MEL_RECIPE, 1, 31, 0};
    seq_set_complexity(q, LANE_MEL_UP, 30);   /* regenerates */
    q->display_rev++;
}

/* 0.22 new instances (and a load into one) open the CHORDS and BASS tabs on JAM: the tests written for their own pages show them first
 * (cvm_1, ubm_1), through the wrapper or on the engine */
static void tap(AEffect *e, const char *key, int v);
static void own_pages(AEffect *e) { tap(e, "cvm_1", 1), tap(e, "ubm_1", 1); }
static void en_own_pages(const mpc_engine_t *en, void *x) { en->set_param(x, "cvm_1", "1"), en->set_param(x, "ubm_1", "1"); }

/* old_state loaded, with 0.18's generated Bass lane (old_bass_on); 0.22 on the CHORDS and BASS pages */
static AEffect *old_start(void) {
    AEffect *e = start_from(old_state());
    if (e) old_bass_on(engine_of(e), 30), run(e, 70, 0), own_pages(e);
    return e;
}

/* 0.9 CHORDS: every new key, on the engine itself (the wrapper reads "_on" only for lit state), and unknown suffixes */
static void test_chords_keys(void) {
    static const char *const TAP_KEYS[] = {"ds_", "fd_", "ia_", "pn_", "mv_", "fs_", "fc_", "fb_", "fo_", "dn_", "rh_", "vo_", "oc_"};
    static const int TAP_N[] = {3, 9, 3, 4, 6, 8, 7, 3, 5, 1, 3, 2, 3};
    static const char *const NUMBERS[] = {"ccol", "cspr", "cpush", "cgate", "cstrum", "cdyn"};
    static const char *const BAD[] = {"fd_0", "fd_10", "fs_9", "ds_4", "oc_4", "fd_", "fd_1x", "fd_1_onx", "fd_1_", "ia_1on",
                                      "itag_on", "lnote_on", "ccolx", "cdyn_on", "fx_1", "dn_2", "pn_5", "mv_7", "fo_6", "fb_4", "fc_8"};
    char key[16], b[64];
    const mpc_engine_t *en = mpc_engine();
    void *x = en->create(NULL);
    int k0 = idx("md_3") + 1, ok = 1, n = 0;
    CHECK(idx("ds_1") == k0 && idx("fd_1") == k0 + 3 && idx("ia_1") == k0 + 12 && idx("pn_1") == k0 + 15 && idx("mv_1") == k0 + 19 &&
          idx("itag") == k0 + 25 && idx("lnote") == k0 + 26 && idx("fs_1") == k0 + 27 && idx("fc_1") == k0 + 35 && idx("fb_1") == k0 + 42 &&
          idx("fo_1") == k0 + 45 && idx("dn_1") == k0 + 50 && idx("rh_1") == k0 + 51 && idx("vo_1") == k0 + 54 && idx("oc_1") == k0 + 56 &&
          idx("ccol") == k0 + 59 && idx("cdyn") == k0 + 64 && !strcmp(PARAMS[k0 + 65].key, "bmode"),
          "0.9 CHORDS params appended after md_3 in order, cdyn last of 0.9");
    for (int t = 0; t < (int)(sizeof TAP_KEYS / sizeof TAP_KEYS[0]); t++)
        for (int i = 1; i <= TAP_N[t]; i++, n++) {
            snprintf(key, sizeof key, "%s%d", TAP_KEYS[t], i);
            int label = en->get_param(x, key, b, sizeof b) > 0;
            snprintf(key, sizeof key, "%s%d_on", TAP_KEYS[t], i);
            int on = en->get_param(x, key, b, sizeof b) > 0 && (!strcmp(b, "0") || !strcmp(b, "1"));
            if (!label || !on) printf("     %s%d: label %d, _on %d\n", TAP_KEYS[t], i, label, on);
            ok &= label && on;
        }
    CHECK(ok, "each of the %d CHORDS tap cells answers its label and _on", n);
    ok = en->get_param(x, "itag", b, sizeof b) > 0 && en->get_param(x, "lnote", b, sizeof b) > 0;
    for (int i = 0; i < 6; i++) ok &= en->get_param(x, NUMBERS[i], b, sizeof b) > 0;
    CHECK(ok, "itag, lnote and the six SHAPE knobs answer");
    ok = 1;
    for (int i = 0; i < (int)(sizeof BAD / sizeof BAD[0]); i++) {
        int got = en->get_param(x, BAD[i], b, sizeof b);
        if (got > 0) printf("     %s answered '%s'\n", BAD[i], b);
        ok &= got <= 0;
    }
    CHECK(ok, "unknown suffixes and indices out of range are rejected");
    en->set_param(x, "fd_10", "1");
    en->set_param(x, "fd_1x", "1");
    en->get_param(x, "fd_5_on", b, sizeof b);
    CHECK(!strcmp(b, "1"), "a set of a bad key tries nothing");
    char rev0[16], rev1[16];
    en->get_param(x, "display_rev", rev0, sizeof rev0);
    en->set_param(x, "cvm_2", "1");   /* 0.24.1 md_ is retired: the CHORDS page's mode cells */
    en->get_param(x, "display_rev", rev1, sizeof rev1);
    CHECK(strcmp(rev0, rev1) != 0, "a mode tap changes display_rev (%s -> %s)", rev0, rev1);
    en->set_param(x, "cvm_1", "1");
    en->get_param(x, "cmode", b, sizeof b);
    en->get_param(x, "display_rev", rev0, sizeof rev0);
    CHECK(!strcmp(b, "0") && strcmp(rev0, rev1) != 0, "cvm_1 sets cmode 0 and changes display_rev (cmode %s, rev %s)", b, rev0);
    en->set_param(x, "gen_1", "1");
    en->get_param(x, "display_rev", rev1, sizeof rev1);
    CHECK(strcmp(rev0, rev1) != 0, "a trigger changes display_rev");
    en->destroy(x);
}

/* 0.9 CHORDS through the wrapper, on a new instance: E minor, 1-6-3-7 (Em C G D), 4 bars of 1-bar chords. IDEAS left the code after
 * 0.24: its cells on the three tabs (KF_RETIRED_24) read as they did with nothing tried, and a tap on any of them changes nothing */
static void test_chords_ideas(void) {
    static char s0[SEQ_STATE_MAX], s1[SEQ_STATE_MAX];
    static const struct { const char *key; int n; } CELLS[] = {{"ds_", 3}, {"fd_", 9}, {"ia_", 3}, {"pn_", 4}, {"mv_", 6}, {"bds_", 3},
        {"bfd_", 9}, {"bia_", 3}, {"bpn_", 4}, {"bmv_", 6}, {"mds_", 3}, {"mfd_", 9}, {"mia_", 3}, {"mpn_", 4}, {"mmv_", 4}};
    char b[64], key[16];
    AEffect *e = old_start();
    const seq_t *q = engine_of(e);
    display(e, "lnote", b);
    CHECK(!strcmp(b, "4 chords \xC2\xB7 1 bar each (chord length is set on GLOBAL)"), "lnote (got '%s')", b);
    display(e, "itag", b);
    CHECK(!strcmp(b, "Near: small changes") && lit(e, "ds_1") && !lit(e, "ds_2"), "Near lit, itag names it (got '%s')", b);
    display(e, "ds_3", b);
    CHECK(!strcmp(b, "Wild"), "ds_3 is Wild (got '%s')", b);
    display(e, "fd_1", b);
    CHECK(!strcmp(b, " ") && lit(e, "fd_5") && !lit(e, "fd_1"), "the field is blank, YOURS (fd_5) lit (got '%s')", b);
    display(e, "ia_1", b);
    CHECK(!strcmp(b, "REROLL"), "ia_1 is REROLL (got '%s')", b);
    display(e, "pn_1", b);
    CHECK(!strcmp(b, "empty"), "pn_1 is empty (got '%s')", b);
    display(e, "mv_3", b);
    CHECK(!strcmp(b, "ADD COLOUR"), "mv_3 is ADD COLOUR (got '%s')", b);
    display(e, "mmv_4", b);
    CHECK(!strcmp(b, "SHIFT >"), "mmv_4 is SHIFT > (got '%s')", b);
    mpc_engine()->get_param(engine_of(e), "state", s0, sizeof s0);
    int undo = q->undo_n, n = 0;
    for (unsigned t = 0; t < sizeof CELLS / sizeof CELLS[0]; t++)
        for (int i = 1; i <= CELLS[t].n; i++, n++) {
            snprintf(key, sizeof key, "%s%d", CELLS[t].key, i);
            tap(e, key, 1);
        }
    mpc_engine()->get_param(engine_of(e), "state", s1, sizeof s1);
    CHECK(!strcmp(s0, s1) && q->undo_n == undo, "a tap on each of the %d retired IDEAS cells changes nothing (state, undo ring)", n);
    e->d(e, effClose, 0, 0, NULL, 0);
}

/* 0.9 SHAPE (retired in 0.17: its cells still answer) and a save with it set. 0.24: FIX's half (0.9 FIX, fs_ fc_ fb_ fo_ dn_) is retired with
 * FIX (unpolled, inert) */
static void test_chords_shape(void) {
    char b[64];
    void *chunk = NULL;
    AEffect *e = old_start(), *f = old_start();
    /* SHAPE: rhythm, voicing, octave, and the six knobs */
    CHECK(lit(e, "crh_2") && lit(e, "vo_2") && lit(e, "oc_2"), "Pulse, Smooth and octave 0 lit on a new instance");
    display(e, "oc_1", b);
    CHECK(!strcmp(b, "-1"), "oc_1 is -1 (got '%s')", b);
    e->setP(e, idx("style_1"), 3 / 9.0f);   /* 0.24.1 crh_, vo_ and oc_ are retired (test_241_retired_cells): style_1, voicing, cpo_ */
    run(e, 40, 0);
    display(e, "style_1", b);
    CHECK(!strcmp(b, "Stabs") && lit(e, "crh_3") && !lit(e, "crh_2"), "style_1 Stabs lights crh_3 (got '%s')", b);
    e->setP(e, idx("style_1"), 0.0f);   /* Manual */
    run(e, 8, 0);   /* a poll: crh_3 unlit again */
    CHECK(!lit(e, "crh_1") && !lit(e, "crh_2") && lit(e, "crh_3"), "Manual is ignored on drawn bars (0.18, ruling R11): crh_3 stays lit");
    e->setP(e, idx("voicing"), 0.0f);
    run(e, 8, 0);
    display(e, "voicing", b);
    CHECK(!strcmp(b, "Close") && lit(e, "vo_1"), "voicing Close lights vo_1 (got '%s')", b);
    tap(e, "cpo_3", 1);
    CHECK(lit(e, "oc_3") && !lit(e, "oc_2"), "cpo_3 sets +1, oc_3 lit");
    static const char *const KN[6] = {"ccol", "cspr", "cpush", "cgate", "cstrum", "cdyn"};
    static const int DEF[6] = {0, 50, 0, 50, 0, 50}, SET[6] = {40, 70, 20, 30, 60, 80};
    int ok = 1;
    for (int i = 0; i < 6; i++) {   /* 0.12: ccol's display is its text (0.17: COLOUR's level); its value still round-trips */
        number(f, KN[i], b);
        ok &= (i == 0 || atoi(b) == DEF[i]) && f->getP(f, idx(KN[i])) == DEF[i] / 100.0f;
        e->setP(e, idx(KN[i]), SET[i] / 100.0f);
        number(e, KN[i], b);
        ok &= (i == 0 || atoi(b) == SET[i]) && e->getP(e, idx(KN[i])) > SET[i] / 100.0f - 0.005f && e->getP(e, idx(KN[i])) < SET[i] / 100.0f + 0.005f;
    }
    CHECK(ok, "the six SHAPE knobs start at 0, 50, 0, 50, 0, 50 and round-trip");

    /* save and load with all of it set */
    intptr_t n = e->d(e, effGetChunk, 0, 0, &chunk, 0);
    if (n > 0 && chunk) f->d(f, effSetChunk, 0, n, chunk, 0);
    ok = 1;
    for (int i = 0; i < 6; i++) {
        number(f, KN[i], b);
        ok &= i == 0 ? f->getP(f, idx(KN[i])) > SET[i] / 100.0f - 0.005f && f->getP(f, idx(KN[i])) < SET[i] / 100.0f + 0.005f : atoi(b) == SET[i];
    }
    CHECK(ok, "the SHAPE knobs restore");
    CHECK(lit(f, "crh_3") && lit(f, "vo_1") && lit(f, "oc_3"), "rhythm, voicing and octave restore");
    e->d(e, effClose, 0, 0, NULL, 0);
    f->d(f, effClose, 0, 0, NULL, 0);
}

