/* ---- 0.12 (Task 4): NAMES and degrees, COLOUR text, NEW PROGRESSION, nine rhythms and NEW RHYTHM, FIX slot count and
 * the playing marker, auditions, move text ---- */

/* MIDI capture on an engine made directly (mpc_engine): its seq_t (first in the instance) gets this emit, as the core tests'.
 * tot_on / tot_off count every note-on and note-off since the capture started, so a test can check nothing is left held. */
static int midi_n, midi_st[256], midi_note[256], midi_vel[256];
static long tot_on, tot_off;
static void cap(void *c, int st, int a, int b) {
    (void)c;
    if ((st & 0xf0) == 0x90 && b > 0) tot_on++;
    else if ((st & 0xf0) == 0x80 || (st & 0xf0) == 0x90) tot_off++;
    if (midi_n < 256) midi_st[midi_n] = st, midi_note[midi_n] = a, midi_vel[midi_n] = b;
    midi_n++;
}
/* note-ons captured on status (0x90 | channel - 1): their count, pitch classes (a bit mask) and the last note */
static int ons(int status, unsigned *pcs, int *last) {
    int n = 0;
    *pcs = 0;
    for (int i = 0; i < midi_n && i < 256; i++)
        if (midi_st[i] == status && midi_vel[i] > 0) n++, *pcs |= 1u << (midi_note[i] % 12), *last = midi_note[i];
    return n;
}
#define PC(a) (1u << (a))

/* every new key answers, on the engine itself; bad keys are rejected; the params are appended in the plan's order */
static void test_12_keys(void) {
    static const char *const BAD[] = {"cnm_0", "cnm_2", "cnp_2", "crh_0", "crh_10", "cnr_2", "fsl_0", "fsl_5", "fsl_1x", "cnm_1_onx",
                                      "crh_", "fsl_", "cslots_on", "cslotsx", "ccol_displayx", "ccol_display_on", "cnm", "crh_1_"};
    char key[16], b[64], r0[16], r1[16];
    const mpc_engine_t *en = mpc_engine();
    void *x = en->create(NULL);
    int k0 = idx("mgat") + 1, ok = 1, n = 0;
    ok = idx("cnm_1") == k0 && idx("cnp_1") == k0 + 1 && idx("cnr_1") == k0 + 11 && idx("cslots") == k0 + 12 && idx("fsl_4") == k0 + 16 &&
         !strcmp(PARAMS[k0 + 17].key, "k_harm");   /* 0.13's follow */
    for (int i = 1; i <= 9; i++) {
        snprintf(key, sizeof key, "crh_%d", i);
        ok &= idx(key) == k0 + 1 + i && PARAMS[idx(key)].no_poll;   /* 0.18: unpolled (the RHYTHM page replaces them) */
    }
    for (int i = 1; i <= 4; i++) {
        snprintf(key, sizeof key, "fsl_%d", i);
        ok &= idx(key) == k0 + 12 + i && PARAMS[idx(key)].no_poll;   /* 0.14: unpolled (fbs_ replaces them) */
    }
    CHECK(ok && idx("fsl_4") == 461, "0.12 params appended after mgat: cnm_1, cnp_1, crh_1..9, cnr_1, cslots, fsl_1..4 (%d params in 0.12)", idx("fsl_4") + 1);
    CHECK(PARAMS[idx("ccol")].dynamic_display && PARAMS[idx("rh_1")].no_poll && PARAMS[idx("rh_3")].no_poll && PARAMS[idx("fs_1")].no_poll &&
          PARAMS[idx("style_1")].nopts == 10 && PARAMS[idx("cslots")].nopts == 3,
          "ccol has dynamic_display, rh_1..3 (and, 0.14, fs_) are unpolled, style_1 has 10 options, cslots 3");
    static const char *const TAPK[] = {"cnm_", "cnp_", "crh_", "cnr_", "fsl_", "rh_"};
    static const int TAPN[] = {1, 1, 9, 1, 4, 3};
    ok = 1;
    for (int t = 0; t < 6; t++)
        for (int i = 1; i <= TAPN[t]; i++, n++) {
            snprintf(key, sizeof key, "%s%d", TAPK[t], i);
            int label = en->get_param(x, key, b, sizeof b) > 0;
            snprintf(key, sizeof key, "%s%d_on", TAPK[t], i);
            int on = en->get_param(x, key, b, sizeof b) > 0 && (!strcmp(b, "0") || !strcmp(b, "1"));
            if (!label || !on) printf("     %s%d: label %d, _on %d\n", TAPK[t], i, label, on);
            ok &= label && on;
        }
    CHECK(ok, "each of the %d new tap cells (and the old rh_ ones) answers its label and _on", n);
    en->get_param(x, "cslots", b, sizeof b);
    en->get_param(x, "ccol_display", key, sizeof key);
    CHECK(!strcmp(b, "0") && !strcmp(key, "Triad"), "cslots answers 0 (\"-\", off FIX), ccol_display 'Triad' (0.17: COLOUR's level; got '%s', '%s')",
          b, key);
    ok = 1;
    for (int i = 0; i < (int)(sizeof BAD / sizeof BAD[0]); i++) {
        int got = en->get_param(x, BAD[i], b, sizeof b);
        if (got > 0) printf("     %s answered '%s'\n", BAD[i], b);
        ok &= got <= 0;
    }
    CHECK(ok, "unknown 0.12 suffixes and indices out of range are rejected");
    static const char *const ACT[] = {"cnm_1", "gl_4", "gl_1"};   /* 0.24.1 cnp_, cnr_ and crh_ are retired: gl_'s NEW PROGRESSION, GEN */
    ok = 1;
    for (int i = 0; i < 3; i++) {
        en->get_param(x, "display_rev", r0, sizeof r0);
        en->set_param(x, ACT[i], "1");
        en->get_param(x, "display_rev", r1, sizeof r1);
        ok &= strcmp(r0, r1) != 0;
    }
    CHECK(ok, "NAMES, NEW PROGRESSION and GEN change display_rev");
    en->set_param(x, "style_1", "1");   /* Sustain: rh_1 answers it too */
    en->get_param(x, "rh_1_on", b, sizeof b);
    en->get_param(x, "rh_1", key, sizeof key);
    CHECK(!strcmp(b, "1") && !strcmp(key, "Sustain"), "rh_1 still answers: lit on Sustain (got %s, '%s')", b, key);
    en->set_param(x, "cmode", "2");   /* 0.24 FIX is retired: cmode Fix does nothing, cslots stays "-" */
    en->get_param(x, "cslots", b, sizeof b);
    CHECK(!strcmp(b, "0") && seq_cview(x) != CVIEW_FIX, "0.24 cmode Fix (retired) does nothing: cslots %s (\"-\")", b);
    en->destroy(x);
}

static int is_name(const char *c) { return *c >= 'A' && *c <= 'G'; }
static int is_degree(const char *c) { return *c && strchr("ivIVb#", *c) != NULL; }

/* The first 4 slots' chords as FIX's slot cells show them (fs_1..4: "2.1  IV  *"), joined by spaces: "i VI III VII" */
static void slots4(AEffect *e, char *out) {
    char key[8], b[64];
    out[0] = 0;
    for (int k = 1; k <= 4; k++) {
        snprintf(key, sizeof key, "fs_%d", k);
        display(e, key, b);
        char *star = strstr(b, "  *");
        if (star) *star = 0;
        strcat(out, k > 1 ? " " : "");
        strcat(out, b + 5);   /* past "1.1  " */
    }
}

/* NAMES switches every CHORDS chord text, both ways; key, scale and progression edits remake them */
static void test_12_names(void) {
    static const char *const KEYS[] = {"fs_1", "fs_2", "fs_3", "fs_4", "fsl_1", "fsl_2", "fsl_3", "fsl_4", "fc_1", "fc_2", "fc_3", "fc_4",
                                       "fc_5", "fc_6", "fc_7", "fb_1", "fb_2", "fb_3"};
    enum { NK = sizeof KEYS / sizeof KEYS[0] };
    char deg[NK][64], nam[NK][64], b[64], from[64], to[64];
    AEffect *e = old_start();
    display(e, "cnm_1", b);
    CHECK(!strcmp(b, "NAMES") && !lit(e, "cnm_1"), "cnm_1 is NAMES, unlit on a new instance (got '%s')", b);
    for (int k = 0; k < NK; k++) display(e, KEYS[k], deg[k]);
    CHECK(!strcmp(deg[0], "1.1  i") && !strcmp(deg[5], "2.1  VI") && !strcmp(deg[9], "ii" DIM) && !strcmp(deg[15], "IV") && !strcmp(deg[17], "bII"),
          "degrees by default: fs_1 '%s', fsl_2 '%s', fc_2 '%s', fb_1 '%s', fb_3 '%s'", deg[0], deg[5], deg[9], deg[15], deg[17]);
    tap(e, "cnm_1", 1);
    for (int k = 0; k < NK; k++) display(e, KEYS[k], nam[k]);
    int ok = lit(e, "cnm_1");
    for (int k = 0; k < NK; k++) {
        const char *d = k < 8 ? deg[k] + 5 : deg[k], *m = k < 8 ? nam[k] + 5 : nam[k];   /* past "1.1  " */
        int good = strcmp(deg[k], nam[k]) && is_degree(d) && is_name(m);
        if (!good) printf("     %s: '%s' / '%s'\n", KEYS[k], deg[k], nam[k]);
        ok &= good;
    }
    slots4(e, b);
    CHECK(ok && !strcmp(b, "Em C G D") && !strcmp(nam[0], "1.1  Em") && !strcmp(nam[9], "F#dim") && !strcmp(nam[15], "A"),
          "NAMES lit: every one of the %d cells is a name (slots '%s', fs_1 '%s', fc_2 '%s', fb_1 '%s')", NK, b, nam[0], nam[9], nam[15]);
    tap(e, "cnm_1", 0);
    ok = !lit(e, "cnm_1");
    for (int k = 0; k < NK; k++) {
        display(e, KEYS[k], b);
        ok &= !strcmp(b, deg[k]);
    }
    CHECK(ok, "NAMES off: every cell back to its degree text");

    e->setP(e, idx("key"), 0.0f);   /* C minor */
    slots4(e, b);
    CHECK(!strcmp(b, "i VI III VII"), "a key change keeps the degrees (got '%s')", b);
    tap(e, "cnm_1", 1);
    slots4(e, b);
    display(e, "fc_4", from);
    display(e, "fs_1", to);
    CHECK(!strcmp(b, "Cm G# D# A#") && !strcmp(from, "Fm") && !strcmp(to, "1.1  Cm"), "in names the key change shows: '%s', '%s', '%s'", b, from, to);
    e->setP(e, idx("scale"), 0.0f);   /* C major */
    slots4(e, b);
    display(e, "fb_1", from);
    CHECK(!strcmp(b, "C Am Em Bdim") && !strcmp(from, "Fm"), "a scale change: '%s', fb_1 '%s'", b, from);
    tap(e, "cnm_1", 0);
    slots4(e, b);
    display(e, "fb_1", from);
    CHECK(!strcmp(b, "I vi iii vii" DIM) && !strcmp(from, "iv"), "and in degrees: '%s', fb_1 '%s'", b, from);
    seq_set_slot(engine_of(e), 1, 3, 0, seq_slot_colour(engine_of(e), 1));   /* slot 2: IV (0.24 FIX's cells are retired: the core) */
    mpc_engine()->set_param(engine_of(e), "panic", "0");   /* a set: the labels (0.24.1 md_ is retired) */
    display(e, "fs_2", b);
    slots4(e, from);
    CHECK(!strcmp(b, "2.1  IV  *") && !strcmp(from, "I IV iii vii" DIM), "a progression edit remakes them: '%s', '%s'", b, from);
    tap(e, "cnm_1", 1);
    display(e, "fs_2", b);
    display(e, "fsl_2", to);
    slots4(e, from);
    CHECK(!strcmp(b, "2.1  F  *") && !strcmp(to, b) && !strcmp(from, "C F Em Bdim"), "and in names: '%s', fsl_2 '%s', '%s'", b, to, from);
    e->d(e, effClose, 0, 0, NULL, 0);
}

/* NEW PROGRESSION and NEW RHYTHM: each one undo step (0.18: NEW RHYTHM leaves drawn bars, no step). 0.24.1 cnp_ and cnr_ are retired
 * (labels only): gl_4 and gl_1 are the same actions */
static void test_12_new_buttons(void) {
    char y0[64], y1[64], b[64], c0[16][12], c1[16][12], c2[16][12];
    AEffect *e = old_start();
    display(e, "cnp_1", b);
    display(e, "cnr_1", y1);
    CHECK(!strcmp(b, "NEW PROGRESSION") && !strcmp(y1, "NEW RHYTHM"), "cnp_1 and cnr_1 labels (got '%s', '%s')", b, y1);
    slots4(e, y0);
    tap(e, "gl_4", 1);
    slots4(e, y1);
    CHECK(strcmp(y0, y1) && !lit(e, "gl_4"), "NEW PROGRESSION makes a new one ('%s' -> '%s'), never lit", y0, y1);
    tap(e, "gl_4", 1);
    tap(e, "act_1", 1);   /* UNDO */
    slots4(e, b);
    CHECK(!strcmp(b, y1), "UNDO takes back one NEW PROGRESSION (got '%s')", b);
    tap(e, "act_1", 1);
    slots4(e, b);
    CHECK(!strcmp(b, y0), "and the next UNDO the first (got '%s')", b);
    lane_cells(e, 1, c0);
    tap(e, "gl_1", 1);
    lane_cells(e, 1, c1);
    tap(e, "gl_1", 1);
    lane_cells(e, 1, c2);
    display(e, "style_1", b);
    CHECK(same_cells(c0, c1) && same_cells(c1, c2) && !strcmp(b, "Pulse") && !lit(e, "gl_1"),
          "NEW RHYTHM leaves the drawn bars (0.18: a load converts the lane), style kept (%s), never lit", b);
    tap(e, "act_1", 1);
    lane_cells(e, 1, c2);
    CHECK(same_cells(c0, c2), "and pushes nothing to undo");
    e->d(e, effClose, 0, 0, NULL, 0);
}

/* the nine rhythm cells map to style_1; style_1's old and new options round trip */
static void test_12_rhythms(void) {
    static const char *const OPT[10] = {"Manual", "Sustain", "Pulse", "Stabs", "Offbeat", "Charleston", "Ballad", "Funk", "Half-time", "Push"};
    static const char *const LAB[9] = {"Sustain", "Pulse", "Stabs", "Offbeat", "Charlstn", "Ballad", "Funk", "Half", "Push"};
    char key[16], b[64];
    void *chunk = NULL;
    AEffect *e = old_start(), *f = old_start();
    int ok = 1;
    for (int i = 1; i <= 9; i++) {
        snprintf(key, sizeof key, "crh_%d", i);
        display(e, key, b);
        ok &= !strcmp(b, LAB[i - 1]) && (int)strlen(b) <= 8;
    }
    CHECK(ok && lit_one(e, "crh_", 9, 2), "crh_1..9 labels, at most 8 characters; Pulse (crh_2) lit on a new instance");
    e->setP(e, idx("style_1"), 1 / 9.0f);   /* 0.24.1 crh_ is retired (labels and lights only): Sustain from style_1 */
    run(e, 8, 0);
    display(e, "style_1", b);
    CHECK(!strcmp(b, "Sustain") && lit_one(e, "crh_", 9, 1), "style_1 Sustain lights crh_1 alone (got '%s')", b);
    e->setP(e, idx("style_1"), 0.0f);
    run(e, 8, 0);
    CHECK(lit_one(e, "crh_", 9, 1), "Manual is ignored on drawn bars (0.18, ruling R11): Sustain stays lit");
    ok = 1;
    for (int k = 0; k <= 9; k++) {
        int w = k ? k : 1;   /* 0.18: Manual leaves the drawn Sustain bars */
        e->setP(e, idx("style_1"), k / 9.0f);
        run(e, 8, 0);
        display(e, "style_1", b);
        ok &= !strcmp(b, OPT[w]) && lit_one(e, "crh_", 9, w);
        intptr_t n = e->d(e, effGetChunk, 0, 0, &chunk, 0);
        if (n > 0 && chunk) f->d(f, effSetChunk, 0, n, chunk, 0);
        run(f, 8, 0);
        display(f, "style_1", b);
        int good = !strcmp(b, OPT[w]) && lit_one(f, "crh_", 9, w);
        if (!good) printf("     option %d: restored as '%s'\n", k, b);
        ok &= good;
    }
    CHECK(ok, "style_1's ten options (old four, new six) set, light their crh_, save and restore (Manual: ignored on drawn bars)");
    e->d(e, effClose, 0, 0, NULL, 0);
    f->d(f, effClose, 0, 0, NULL, 0);
}

/* the FIX picks audition: a chord, borrow or colour plays the slot's chord on the Chords channel; a note or octave the step's
 * note on the lane's; REST nothing; the lit cell's tap (no change) plays again; nothing is left held */
static void test_12_auditions(void) {
    const mpc_engine_t *en = mpc_engine();
    void *x = en->create(NULL);
    unsigned pcs = 0;
    int last = 0, m;
    en->set_param(x, "state", old_state());   /* the pre-0.15 start: E minor */
    old_bass_on(x, 30);
    ((seq_t *)x)->emit = cap;
    tot_on = tot_off = 0;
    en->set_param(x, "ch_2", "4");   /* Bass on channel 5 */
#define AUD(key, val) (midi_n = 0, en->set_param(x, key, val), en->song_pos(x, -1.0, 120.0, 0, 128))
    AUD("fc_4", "1");   /* 0.24 FIX's chord, borrow and colour cells are retired: nothing plays, nothing changes */
    AUD("fb_1", "1");
    AUD("fo_2", "1");
    CHECK(ons(0x90, &pcs, &last) == 0 && seq_slot_deg(x, 0) == 0 && seq_slot_src(x, 0) == 0, "0.24: fc_, fb_, fo_ (FIX, retired) play and "
          "change nothing");
    {   /* 0.24.1 FIX A NOTE's and FIX NOTE's cells are retired too (TAPR) */
        static const char *const NOTE_CELLS[] = {"bnk_8", "bno_3", "brs_1", "bst_3", "mnk_1", "mno_3", "mrt_1", "mst_3"};
        static char before[SEQ_STATE_MAX], after[SEQ_STATE_MAX];
        int ok = 1;
        en->get_param(x, "state", before, sizeof before);
        for (unsigned i = 0; i < sizeof NOTE_CELLS / sizeof NOTE_CELLS[0]; i++) {
            AUD(NOTE_CELLS[i], "1");
            AUD(NOTE_CELLS[i], "0");
            ok &= midi_n == 0 || (ons(0x94, &pcs, &last) == 0 && ons(0x92, &pcs, &last) == 0);
        }
        en->get_param(x, "state", after, sizeof after);
        CHECK(ok && !strcmp(before, after), "0.24.1: bnk_, bno_, brs_, bst_, mnk_, mno_, mrt_, mst_ (FIX NOTE, retired) play and change nothing");
    }
    midi_n = 0;
    seq_audition_chord(x, 0);   /* a live audition (PHRASE's picks), for the note-offs below */
    en->song_pos(x, -1.0, 120.0, 0, 128);
    m = midi_n;
    CHECK(m > 0, "seq_audition_chord plays (%d notes)", m);
#undef AUD
    for (int k = 0; k < 400; k++) en->song_pos(x, -1.0, 120.0, 0, 128);   /* over a second, stopped */
    CHECK(tot_on > 0 && tot_on == tot_off, "every audition note ends (%ld on, %ld off)", tot_on, tot_off);
    en->destroy(x);
}

/* A host restoring a 0.11 project's style_1 as its old normalised value (k/3 of 4 options) lands on option 3k of the 10:
 * the engine ignores it, so the project keeps its style and re-saves unchanged (Sustain, Pulse, Stabs) */
static void test_12_style_1_from_0_11(void) {
    static const char *const NAME[4] = {"", "Sustain", "Pulse", "Stabs"};
    char st[256], b[64];
    for (int k = 1; k <= 3; k++) {
        void *chunk = NULL;
        static char before[SEQ_STATE_MAX];
        snprintf(st, sizeof st, "csq2|gv=1|k=4|s=1|A.len=4|A.cl=16|A.h=30,1|A.prog=0526|A.voi=1|ch=1,2,3|A1=0:|A1.g=%d,1,30|"
                 "A2=0:|A2.g=4,1,30|A3=0:|A3.g=8,1,63|A4=0:", k);
        AEffect *e = VSTPluginMain(host);
        e->d(e, effSetChunk, 0, (int)strlen(st) + 1, st, 0);
        run(e, 8, 0);
        intptr_t n = e->d(e, effGetChunk, 0, 0, &chunk, 0);
        snprintf(before, sizeof before, "%.*s", (int)n, n > 0 && chunk ? (const char *)chunk : "");
        e->setP(e, idx("style_1"), k / 3.0f);   /* 0.11's value: option 3k now */
        run(e, 8, 0);
        n = e->d(e, effGetChunk, 0, 0, &chunk, 0);
        display(e, "style_1", b);
        CHECK(n > 0 && chunk && !strncmp(before, (const char *)chunk, (size_t)n) && strstr(before, "A1.g=") && !strcmp(b, NAME[k]),
              "a 0.11 %s project: the restored style_1 %d/3 is ignored, it re-saves unchanged (style_1 '%s')", NAME[k], k, b);
        e->d(e, effClose, 0, 0, NULL, 0);
    }
}

