/* 0.13: the stepped knobs (plan decision 5), in params.json order, with their option counts */
static const char *const K13[13] = {"k_harm", "k_col", "k_spr", "k_bmov", "k_bsyn", "k_boct", "k_breg", "k_mrng", "k_mlea", "k_msyn",
                                    "k_mten", "k_mans", "k_mreg"};
static const int K13_N[13] = {4, 17, 3, 5, 5, 5, 5, 2, 2, 2, 2, 3, 3};
static const char *const VK17[4] = {"k_vcol", "k_vinv", "k_vspr", "k_vstr"};   /* 0.17 knobs 2-5 */
static const char *const KS18[4] = {"k_s2", "k_s3", "k_s4", "k_s5"};               /* 0.18 the mode-following knobs 2-5 */
static const char *const KB19[4] = {"k_b2", "k_b3", "k_b4", "k_b5"};               /* 0.19 the BASS tab's mode-following knobs 2-5 */
static const char *const KJ21[7] = {"k_j2", "k_j3", "k_j4", "k_j5", "k_j6", "k_j7", "k_j8"};   /* 0.20 the MELODY tab's mode-following
                                                                                         * knobs 2-5, 0.21 2-8 */
static const char *const K22[6] = {"k_s1", "k_s6", "k_s8", "k_b1", "k_b6", "k_b8"};   /* 0.22 knob 1 (numbers) and knobs 6 and 8 */
static const char *const K24[2] = {"k_s7", "k_b7"};   /* 0.24 knob 7 */
#define NKOPT 40   /* KOPTIONS: K13, VK17, KS18, KB19, KJ21, 0.22 K22, 0.24 K24 */
static const char *kopt(int t) {   /* KOPTIONS order */
    return t < 13 ? K13[t] : t < 17 ? VK17[t - 13] : t < 21 ? KS18[t - 17] : t < 25 ? KB19[t - 21] : t < 32 ? KJ21[t - 25] : t < 38 ? K22[t - 32]
                                                                                                                        : K24[t - 38];
}
static const char *const OLD13[13] = {"harmony", "ccol", "cspr", "bmov", "bsync", "boct", "breg", "mrng", "mlea", "msyn", "mten",
                                      "mans", "mreg"};
static const char *const SMOOTH13[14] = {"cx_1", "cx_2", "cx_3", "swing", "gate", "dyn", "cgate", "cdyn", "cstrum", "cpush", "bpush",
                                         "bgate", "bacc", "mgat"};

static int eng_num(const mpc_engine_t *en, void *x, const char *key) {
    char b[64];
    en->get_param(x, key, b, sizeof b);
    return atoi(b);
}
static void eng_set(const mpc_engine_t *en, void *x, const char *key, int v) {
    char b[16];
    snprintf(b, sizeof b, "%d", v);
    en->set_param(x, key, b);
}
static void eng_disp(const mpc_engine_t *en, void *x, const char *key, char *buf) {   /* <key>_display */
    char k[48];
    snprintf(k, sizeof k, "%s_display", key);
    buf[0] = 0;
    en->get_param(x, k, buf, 64);
}

/* every new key answers; bad ones are rejected; the params are appended in the plan's order, flagged as it says */
static void test_13_keys(void) {
    static const char *const BAD[] = {"k_harmx", "k_harm_on", "k_col_", "cshtag_on", "cshtagx", "k_harm_displayx", "x_display", "_display",
                                      "k_display", "cx_4_display", "harmony_display", "k_mreg_display_on"};
    char b[64];
    const mpc_engine_t *en = mpc_engine();
    void *x = en->create(NULL);
    int k0 = idx("fsl_4") + 1, ok = idx("cshtag") == k0 + 13 && !strcmp(PARAMS[k0 + 13].key, "cshtag") && PARAMS[k0 + 13].string_display &&
                                   PARAMS[k0 + 13].no_poll;   /* 0.17: cshtag leaves the CHORDS tab with SHAPE */
    for (int i = 0; i < 13; i++) {
        const param_t *p = &PARAMS[k0 + i];
        int good = !strcmp(p->key, K13[i]) && p->nopts == K13_N[i] && p->qlink_ticks == 3 && p->dynamic_display && p->no_poll &&
                   PARAMS[idx(OLD13[i])].no_poll && !PARAMS[idx(OLD13[i])].nopts;
        if (!good) printf("     %s\n", p->key);
        ok &= good;
    }
    CHECK(ok && idx("cshtag") == 475, "0.13 params appended after fsl_4: k_harm..k_mreg (options, qlink_ticks 3, dynamic_display), cshtag; "
          "the old knobs unpolled; 0.17: HARMONY, COLOUR and SPREAD's too; 0.19 the BASS ones; 0.20 the MELODY ones (%d params)", NPARAMS);
    ok = PARAMS[idx("act_2")].no_poll && !PARAMS[idx("act_1")].no_poll && PARAMS[idx("ccol")].dynamic_display && !PARAMS[idx("cx_4")].dynamic_display;
    for (int i = 0; i < 14; i++) ok &= PARAMS[idx(SMOOTH13[i])].dynamic_display;
    CHECK(ok, "the smooth knobs have dynamic_display (cx_4 not), act_2 (ALL NOTES OFF) is unpolled");
    ok = 1;
    for (int i = 0; i < 13; i++) {
        int got = en->get_param(x, K13[i], b, sizeof b), v = atoi(b);
        eng_disp(en, x, K13[i], b);
        if (got <= 0 || v < 0 || v >= K13_N[i] || !b[0]) printf("     %s: %d, '%s'\n", K13[i], v, b);
        ok &= got > 0 && v >= 0 && v < K13_N[i] && b[0];
    }
    for (int i = 0; i < 14; i++) {
        eng_disp(en, x, SMOOTH13[i], b);
        if (!b[0]) printf("     %s_display: none\n", SMOOTH13[i]);
        ok &= b[0] != 0;
    }
    ok &= en->get_param(x, "cshtag", b, sizeof b) > 0 && !strcmp(b, " ");
    CHECK(ok, "every stepped knob answers its step and text, every smooth knob its text, cshtag ' ' (no move)");
    ok = 1;
    for (int i = 0; i < (int)(sizeof BAD / sizeof BAD[0]); i++) {
        int got = en->get_param(x, BAD[i], b, sizeof b);
        if (got > 0) printf("     %s answered '%s'\n", BAD[i], b);
        ok &= got <= 0;
    }
    CHECK(ok, "unknown 0.13 keys and suffixes are rejected");
    en->set_param(x, "act_2", "1");   /* ALL NOTES OFF still answers (off the skin from 0.13) */
    en->get_param(x, "act_2", b, sizeof b);
    CHECK(!strcmp(b, "ALL NOTES OFF"), "act_2 still answers (got '%s')", b);
    en->destroy(x);
}

/* the played MIDI of the whole loop (every lane), as a hash: an engine made with mpc_engine, from bar 1 */
static unsigned fp_hash;
static void fp_cap(void *c, int st, int a, int b) {
    (void)c;
    fp_hash = (fp_hash ^ (unsigned)st) * 16777619u;
    fp_hash = (fp_hash ^ (unsigned)a) * 16777619u;
    fp_hash = (fp_hash ^ (unsigned)b) * 16777619u;
}
static unsigned played(const mpc_engine_t *en, void *x) {
    seq_t *q = x;
    double ppq = 0;
    int blocks = (int)(seq_bars(q) * 4 * 0.5 * 44100 / 128) + 2;
    q->emit = fp_cap;
    fp_hash = 2166136261u;
    for (int k = 0; k < blocks; k++, ppq += 128 * 2.0 / 44100) en->song_pos(x, ppq, 120.0, 1, 128);
    for (int k = 0; k < 4; k++) en->song_pos(x, ppq, 120.0, 0, 128);
    return fp_hash;
}

/* 0.24.1 MELODY's RECIPE cells (mty_, mo1_..mo3_) are retired: what a tap on mty_<t + 1> did (nothing on a JAM lane, KF_RETIRED_MEL),
 * through the core, then a set (the labels) */
static void mel_type_tap(const mpc_engine_t *en, void *x, int t) {
    if (seq_style(x, LANE_MEL_UP) != GEN_MEL_JAM && (seq_mel_type(x) != t || seq_mel_is_classic(x))) seq_mel_set_type(x, t);
    en->set_param(x, "panic", "0");
}

/* A fresh engine set up by `setup` ("key=value" pairs, applied in order; "mel_type=t" mel_type_tap, "mel_opt=w.i" a RECIPE option),
 * the stepped knob at step i, then `after`; its loop */
static unsigned step_sound(const char *const *setup, const char *knob, int i, const char *const *after, int *core) {
    const mpc_engine_t *en = mpc_engine();
    void *x = en->create(NULL);
    char k[32];
    for (; setup && *setup; setup++) {
        const char *eq = strchr(*setup, '=');
        if (!strcmp(*setup, "old_bass")) {   /* 0.19: 0.18's generated Bass, which the retired keys still edit */
            old_bass_on(x, 30);
            continue;
        }
        if (!strcmp(*setup, "old_mel")) {   /* 0.20: 0.19's INIT Melody (a recipe), which the retired MELODY keys still edit */
            old_mel_on(x);
            continue;
        }
        if (!strcmp(*setup, "eighths")) {    /* 0.19: Eighths in every Bass bar, every gap a hit (cx_2 100), MOVEMENT Some: knobs 3-5 show */
            en_own_pages(en, x);   /* 0.22: the BASS page's knobs */
            seq_rhythm_pick(x, LANE_BASS, 3);
            seq_set_bknob(x, BK_MOV, 2);
            en->set_param(x, "cx_2", "100");
            continue;
        }
        if (!strncmp(*setup, "mel_type=", 9)) {
            mel_type_tap(en, x, atoi(eq + 1));
            continue;
        }
        if (!strncmp(*setup, "mel_opt=", 8)) {
            if (seq_style(x, LANE_MEL_UP) != GEN_MEL_JAM) seq_mel_set_opt(x, atoi(eq + 1), atoi(strchr(eq, '.') + 1));
            en->set_param(x, "panic", "0");
            continue;
        }
        snprintf(k, sizeof k, "%.*s", (int)(eq - *setup), *setup);
        en->set_param(x, k, eq + 1);
    }
    eng_set(en, x, knob, i);
    for (; after && *after; after++) en->set_param(x, *after, "1");
    unsigned h = played(en, x);
    *core = eng_num(en, x, knob);
    en->destroy(x);
    return h;
}

/* Review Focus 1: every step of every stepped knob plays differently (the loop's MIDI), in a context where the knob acts */
static void test_13_steps_audible(void) {
    static const char *const BASS[] = {"old_bass", "style_2=3", "cx_2=90", "length=3", NULL};   /* Walk, busy, 8 bars */
    static const char *const BASS19[] = {"eighths", NULL};                                       /* 0.19: a drawn Bass, every step a hit */
    static const char *const MEL[] = {"old_mel", "mel_type=3", "length=3", NULL};                  /* a recipe Hook */
    static const char *const APPR[] = {"old_mel", "mel_type=6", "mel_opt=1.0", "length=3", NULL};  /* Approach by scale steps: TENSION acts */
    static const char *const NEWPROG[] = {"gl_4", "gl_4", "gl_4", NULL};   /* HARMONY acts on NEW PROGRESSION */
    /* k_spr is not here: 0.17's SPREAD is k_vspr (below); k_spr only sets cspr, which no longer sounds */
    static const struct { const char *knob; const char *const *setup, *const *after; } T[] = {
        {"k_harm", NULL, NEWPROG}, {"k_bmov", BASS, NULL}, {"k_bsyn", BASS, NULL}, {"k_boct", BASS, NULL},
        {"k_breg", BASS, NULL}, {"k_mrng", MEL, NULL}, {"k_mlea", MEL, NULL}, {"k_msyn", MEL, NULL}, {"k_mten", APPR, NULL},
        {"k_mans", MEL, NULL}, {"k_mreg", MEL, NULL}, {"k_b3", BASS19, NULL}, {"k_b4", BASS19, NULL}, {"k_b5", BASS19, NULL}};
    for (unsigned t = 0; t < sizeof T / sizeof T[0]; t++) {
        int n = PARAMS[idx(T[t].knob)].nopts, ok = 1, core;
        unsigned h[5];
        for (int i = 0; i < n; i++) {
            h[i] = step_sound(T[t].setup, T[t].knob, i, T[t].after, &core);
            ok &= core == i;
            for (int j = 0; j < i; j++) ok &= h[i] != h[j];
        }
        if (!ok) for (int i = 0; i < n; i++) printf("     %s step %d: %08x\n", T[t].knob, i, h[i]);
        CHECK(ok, "%s: each of its %d steps plays the loop differently", T[t].knob, n);
    }
    /* 0.17 knobs 2-4 (k_col's 17 rank steps are retired): every step of COLOUR, INVERSION and SPREAD plays the loop differently.
     * STRUM is left out: its steps move note times, which this hash does not see */
    for (int t = 0; t < 3; t++) {
        int n = PARAMS[idx(VK17[t])].nopts, ok = 1, core;
        unsigned h[6];
        for (int i = 0; i < n; i++) {
            h[i] = step_sound(NULL, VK17[t], i, NULL, &core);
            ok &= core == i;
            for (int j = 0; j < i; j++) ok &= h[i] != h[j];
        }
        CHECK(ok, "%s: each of its %d steps plays the loop differently", VK17[t], n);
    }
}

/* Q-Link: three small moves (MPC: the read-back value + 1/128) move one step, one or two do not; a set one option away moves one */
static void test_13_qlink(void) {
    AEffect *e = old_start();
    int ok = 1;
    for (int t = 0; t < NKOPT; t++) {
        if (t == 1 || t == 32 || t == 35) continue;   /* k_col: retired in 0.17, a set does nothing; 0.22 knob 1 is a number (test_22_k1_modes) */
        const char *k = kopt(t);   /* 0.18: the slots on CHORDS too */
        int i = idx(k), n = PARAMS[i].nopts, s0 = (int)lroundf(e->getP(e, i) * (n - 1)), dir = s0 < n - 1 ? 1 : -1, s;
        for (int ev = 1; ev <= 3; ev++) {
            e->setP(e, i, e->getP(e, i) + dir / 128.0f);
            run(e, 1, 0);
            s = (int)lroundf(e->getP(e, i) * (PARAMS[i].nopts - 1));
            int want = ev < 3 ? s0 : s0 + dir;
            if (ev == 3 && !strcmp(k, "k_j8") && s0 == 2 && dir > 0) want = 4;   /* 0.21 Amendment 1 k_j8: TIME's 3 steps on 5 options read 0, 2, 4 (R4) */
            if (s != want) printf("     %s event %d: step %d (from %d)\n", k, ev, s, s0);
            ok &= s == want;
        }
        s0 = s;
        if (t != 21 && t != 33 && t != 36 && s0 + dir >= 0 && s0 + dir < n) {   /* a set one option on (0.19 k_b2: MOVEMENT's 5 steps on
                                                                                  * 6 options land scaled, test_19_slot_follows_bass_mode; 0.22
                                                                                  * PUSH's 5 on k_s6's and k_b6's 6, test_22_push_dyn_steps) */
            e->setP(e, i, (float)(s0 + dir) / (PARAMS[i].nopts - 1));
            run(e, 1, 0);
            s = (int)lroundf(e->getP(e, i) * (PARAMS[i].nopts - 1));
            if (s != s0 + dir) printf("     %s set: step %d, want %d\n", k, s, s0 + dir);
            ok &= s == s0 + dir;
        }
    }
    CHECK(ok, "every stepped knob (0.17: k_vcol..k_vstr too, 0.18 k_s2..5, 0.19 k_b2..5; k_col retired): 3 Q-Link events move one step "
          "(1 or 2 none), a set one option on moves one");
    e->d(e, effClose, 0, 0, NULL, 0);
}

/* 0.19: buf without its Bass lanes' fields (`<P>2=`, `<P>2.*`), which a load converts to DRAWN bars */
static void strip_bass(char *buf) {
    for (char *f = strchr(buf, '|'); f; f = strchr(f, '|')) {
        if (f[1] >= 'A' && f[1] <= 'F' && f[2] == '2' && (f[3] == '=' || f[3] == '.')) {
            char *e = strchr(f + 1, '|');
            memmove(f, e ? e : f + strlen(f), strlen(e ? e : f + strlen(f)) + 1);
        } else {
            f++;
        }
    }
}

/* A 0.12 project: the old knobs at values between steps load and re-save unchanged, MPC echoing every step it reads; the
 * text names the nearest step; a step set then moves the value onto it. 0.19: the load converts the Bass to DRAWN bars, its old
 * MOVEMENT, OCTAVES and REGISTER going to the note settings (SYNC dropped): those four knobs read their neutral values after it */
static void test_13_old_values(void) {
    static const int OLDV[13] = {60, 40, 65, 33, 12, 90, 37, 47, 47, 52, 40, 66, 30};
    static const char *const WANT[13] = {"Colourful", NULL, "Open", "A little", "None", "All", "Low", "Full", "Steps", "On the beat",
                                         "Approach only", "Flip", "Middle"};   /* nearest, or the band it plays in */
    static char s1[SEQ_STATE_MAX], s2[SEQ_STATE_MAX];
    void *chunk = NULL;
    char b[64];
    AEffect *a = old_start(), *f = old_start();
    a->setP(a, idx("style_2"), 1.0f);   /* Walk, so the Bass transforms act */
    run(a, 8, 0);
    for (int t = 0; t < 13; t++) a->setP(a, idx(OLD13[t]), OLDV[t] / 100.0f);
    run(a, 8, 0);
    intptr_t n = a->d(a, effGetChunk, 0, 0, &chunk, 0);
    snprintf(s1, sizeof s1, "%.*s", (int)n, (const char *)chunk);
    f->d(f, effSetChunk, 0, (int)strlen(s1) + 1, s1, 0);
    run(f, 8, 0);
    int ok = 1;
    static const int BNEUTRAL[4] = {0, 0, 0, 50};   /* 0.19: MOVEMENT, SYNC, OCTAVES, REGISTER after the conversion */
    for (int t = 0; t < 13; t++) {
        int i = idx(K13[t]), bass = t >= 3 && t <= 6;
        f->setP(f, i, f->getP(f, i));   /* MPC echoing the step it read */
        run(f, 2, 0);
        display(f, K13[t], b);
        if (!bass && WANT[t] && strncmp(b, WANT[t], strlen(WANT[t]))) printf("     %s: '%s', want '%s'\n", K13[t], b, WANT[t]);
        ok &= bass || !WANT[t] || !strncmp(b, WANT[t], strlen(WANT[t]));
    }
    n = f->d(f, effGetChunk, 0, 0, &chunk, 0);
    snprintf(s2, sizeof s2, "%.*s", (int)n, (const char *)chunk);
    for (int t = 0; t < 13; t++) ok &= lroundf(f->getP(f, idx(OLD13[t])) * 100) == (t >= 3 && t <= 6 ? BNEUTRAL[t - 3] : OLDV[t]);
    strip_bass(s1);
    strip_bass(s2);
    CHECK(ok && !strcmp(s1, s2), "a 0.12 state's knob values between steps load and re-save unchanged, each step echoed; texts name the nearest step "
          "(0.19: but the Bass lane's, converted)");
    const bass_set_t want = {29, 0, 0, {4, 4, 1, -1}};   /* Upright Walk: MOVEMENT 33 under its 4, OCTAVES 90 and REGISTER 37 at their steps */
    CHECK(!memcmp(&((const seq_t *)engine_of(f))->part[0].bass.set, &want, sizeof want), "the old Bass knobs load into the note settings");
    display(a, "k_bmov", b);   /* 0.19: on the generated Bass the state came from */
    CHECK(!strncmp(b, "A little" DOT, 12) && b[12] >= '0' && b[12] <= '9', "the Bass step text counts its notes (got '%s')", b);
    f->setP(f, idx("k_harm"), 2 / 3.0f);   /* Rare */
    f->setP(f, idx("k_spr"), 1.0f);        /* Wide */
    f->setP(f, idx("k_mlea"), 1.0f);       /* Leaps */
    run(f, 2, 0);
    CHECK(lroundf(f->getP(f, idx("harmony")) * 100) == 67 && lroundf(f->getP(f, idx("cspr")) * 100) == 80 &&
          lroundf(f->getP(f, idx("mlea")) * 100) == 80, "a step set moves the old knob onto the step's value (67, 80, 80)");
    a->d(a, effClose, 0, 0, NULL, 0);
    f->d(f, effClose, 0, 0, NULL, 0);
}

/* the knob texts at representative values; each part's own */
static void test_13_texts(void) {
    static const struct { const char *key; int v; const char *want; } T[] = {
        {"swing", 0, "Straight"}, {"swing", 25, "Swing 25%"}, {"swing", 100, "Triplet"},
        {"gate", 0, "Gate 20%"}, {"gate", 50, "Gate 100%"}, {"gate", 100, "Gate 200%"}, {"cgate", 25, "Gate 60%"},
        {"bgate", 75, "Gate 150%"}, {"mgat", 40, "Gate 84%"},
        {"dyn", 0, "Dyn x0.4"}, {"dyn", 50, "Dyn x1.0"}, {"dyn", 100, "Dyn x1.6"},
        {"cdyn", 0, "Flat"}, {"cdyn", 50, "Even"}, {"cdyn", 80, "Accented +30"}, {"bacc", 20, "Softer -30"},
        {"cstrum", 0, "Together"}, {"cstrum", 100, "Strum 1/64"}, {"cstrum", 50, "Strum 1/128"},
        {"cpush", 0, "On the beat"}, {"cpush", 100, "Ahead 1/32"}, {"cpush", 50, "Ahead 1/64"}, {"bpush", 25, "Ahead 1/128"},
        {"k_harm", 3, "Rare + borrow"}, {"k_harm", 1, "Colourful"}, {"k_spr", 2, "Wide"}, {"k_b5", 0, "Lowest"},
        {"k_mrng", 0, "Narrow"}, {"k_mans", 2, "Shift"}, {"k_mreg", 2, "High"}, {"k_b2", 0, "None"}, {"k_col", 0, "Triad"}, {"k_col", 1, "Triad"}};   /* 0.17: COLOUR's level; a k_col set does nothing */
    const mpc_engine_t *en = mpc_engine();
    void *x = en->create(NULL);
    seq_t *q = x;
    char b[64], want[32];
    int ok = 1;
    en_own_pages(en, x);   /* 0.22: the CHORDS and BASS pages' knob texts */
    old_mel_on(x);   /* 0.20: the retired MELODY knobs on 0.19's INIT Arp */
    for (unsigned i = 0; i < sizeof T / sizeof T[0]; i++) {
        eng_set(en, x, T[i].key, T[i].v);
        eng_disp(en, x, T[i].key, b);
        if (strcmp(b, T[i].want)) printf("     %s %d: '%s', want '%s'\n", T[i].key, T[i].v, b, T[i].want);
        ok &= !strcmp(b, T[i].want);
    }
    CHECK(ok, "%d knob texts at representative values (Straight, Gate 20%%, Dyn x1.0, Accented +30, Strum 1/64, Ahead 1/32, steps)",
          (int)(sizeof T / sizeof T[0]));
    ok = 1;
    for (int lane = 0; lane < 3; lane++) {   /* COMPLEXITY: the lane's onsets per bar over the loop */
        static const char *const CX[3] = {"cx_1", "cx_2", "cx_3"};
        for (int c = 0; c <= 100; c += 50) {
            const seq_part_t *p = &q->part[seq_part(q)];
            int on = 0;
            eng_set(en, x, CX[lane], c);
            for (int k = 0; k < p->bars * 16; k++) on += p->lane[lane].steps[k].on != 0;
            int t = (2 * on + p->bars) / (2 * p->bars);   /* rounded; "<1" under half an onset a bar */
            if (t) snprintf(want, sizeof want, "%d per bar", t);
            else snprintf(want, sizeof want, "<1 per bar");
            if (!lane) {   /* 0.18: a drawn Chords lane's is the shown bar's hits (bar 1, stopped) */
                t = seq_bar_hits(q, LANE_CHORDS, 0);
                snprintf(want, sizeof want, "%d %s", t, t == 1 ? "hit a bar" : "hits a bar");
            } else if (lane == 1) {   /* 0.19: a drawn Bass lane's, the BASS page's centre bar's notes (bar 1, stopped) */
                t = seq_bar_hits(q, LANE_BASS, 0);
                snprintf(want, sizeof want, "%d %s", t, t == 1 ? "note" : "notes");
            }
            eng_disp(en, x, CX[lane], b);
            if (strcmp(b, want)) printf("     %s %d: '%s', want '%s'\n", CX[lane], c, b, want);
            ok &= !strcmp(b, want);
        }
    }
    CHECK(ok, "COMPLEXITY's text is each lane's onsets per bar, rounded ('12 per bar'); 0.18 Chords: the shown bar's hits ('6 hits a bar'); "
          "0.19 Bass: its notes ('5 notes')");
    eng_disp(en, x, "k_mten", b);
    CHECK(!strcmp(b, "Approach only"), "TENSION off Approach: '%s'", b);
    mel_type_tap(en, x, MEL_APPR);   /* Approach starts at TENSION 60: inside (chromatic from 67) */
    eng_disp(en, x, "k_mten", b);
    CHECK(!strcmp(b, "Inside"), "on Approach: '%s', the band 60 plays in", b);
    /* the Bass transforms' counts: the notes that knob alone changes (a twin with it at 0) */
    static const char *const KB[3] = {"k_bmov", "k_bsyn", "k_boct"};
    ok = 1;
    for (int t = 0; t < 3; t++) {
        void *y = en->create(NULL), *z = en->create(NULL);
        old_bass_on(y, 30), old_bass_on(z, 30);   /* 0.19: 0.18's generated Bass (a DRAWN one ignores these retired knobs) */
        en->set_param(y, "style_2", "3"), en->set_param(z, "style_2", "3");
        eng_set(en, y, "cx_2", 90), eng_set(en, z, "cx_2", 90);
        eng_set(en, y, KB[t], 3);   /* Lots */
        const seq_lane_t *ly = &((seq_t *)y)->part[0].lane[1], *lz = &((seq_t *)z)->part[0].lane[1];
        int cnt = 0;
        for (int k = 0; k < 64; k++)
            cnt += t == 0 ? ly->steps[k].on && ly->steps[k].tone != lz->steps[k].tone
                 : t == 1 ? ly->steps[k].on && !lz->steps[k].on : ly->steps[k].on && ly->steps[k].oct != lz->steps[k].oct;
        snprintf(want, sizeof want, "Lots" DOT "%d", cnt);
        eng_disp(en, y, KB[t], b);
        if (strcmp(b, want) || !cnt) printf("     %s: '%s', want '%s'\n", KB[t], b, want);
        ok &= !strcmp(b, want) && cnt > 0;
        en->destroy(y);
        en->destroy(z);
    }
    CHECK(ok, "MOVEMENT, SYNC and OCTAVES count the notes each changes ('Lots \xC2\xB7 N')");
    /* per part: the Verse's text, then the Chorus's own once it plays */
    eng_set(en, x, "cdyn", 80);
    en->set_param(x, "pt_4", "1");   /* Chorus, stopped: at once */
    eng_set(en, x, "cdyn", 20);
    eng_disp(en, x, "cdyn", b);
    ok = !strcmp(b, "Softer -30");
    en->set_param(x, "pt_2", "1");   /* the Verse again */
    eng_disp(en, x, "cdyn", b);
    CHECK(ok && !strcmp(b, "Accented +30"), "each part has its own text (Verse '%s')", b);
    en->destroy(x);
}

/* decision 2: degrees with the dim sign, FIX and rows (0.13's IDEAS cards left with IDEAS) */
