    seq_set_slot(q, 1, seq_slot_deg(q, 1), seq_slot_src(q, 1), COL_SUS4);   /* slot 2 sus4 */
    seq_set_slot(q, 0, 1, 0, COL_ADD9);   /* slot 1: ii dim, keeping its add9; then sus4 */
    seq_set_slot(q, 0, 1, 0, COL_SUS4);
