/* decision 4: cshtag is the Chords move text (as itag's), else " "; NEW RHYTHM changing the style refreshes style_1 and crh_ (0.18: on drawn bars it changes nothing) */
static void test_13_shape_feedback(void) {
    static const char *const OPT[10] = {"Manual", "Sustain", "Pulse", "Stabs", "Offbeat", "Charleston", "Ballad", "Funk", "Half-time", "Push"};
    char b[64], c[64], r0[16], r1[16];
    AEffect *e = old_start();
    display(e, "cshtag", b);
    CHECK(!strcmp(b, " "), "cshtag is ' ' before a move (got '%s')", b);
    e->setP(e, idx("style_1"), 1 / 9.0f);   /* Sustain (0.24.1 crh_ and cnr_ are retired: style_1, gl_1) */
    e->setP(e, idx("cx_1"), 0.0f);   /* one hit a chord: 0.17's NEW RHYTHM moved on to Ballad */
    run(e, 8, 0);
    tap(e, "gl_1", 1);
    run(e, 40, 0);
    display(e, "cshtag", b);
    display(e, "itag", c);
    CHECK(!strcmp(b, " ") && strncmp(c, "NEW RHYTHM", 10), "NEW RHYTHM leaves drawn bars (0.18): no text on cshtag or itag ('%s', '%s')", b, c);
    display(e, "style_1", b);
    CHECK(!strcmp(b, OPT[1]) && lit_one(e, "crh_", 9, 1), "and style_1 stays '%s', crh_1 lit alone", b);
    e->d(e, effClose, 0, 0, NULL, 0);
    /* on the engine: the tap and the trigger both bump display_rev */
    const mpc_engine_t *en = mpc_engine();
    void *x = en->create(NULL);
    en->get_param(x, "display_rev", r0, sizeof r0);
    en->set_param(x, "gl_1", "1");
    en->get_param(x, "display_rev", r1, sizeof r1);
    int ok = strcmp(r0, r1) != 0;
    en->set_param(x, "gen_1", "1");
    en->get_param(x, "display_rev", r0, sizeof r0);
    CHECK(ok && strcmp(r0, r1), "NEW RHYTHM (gl_1, gen_1) bumps display_rev");
    en->destroy(x);
}

/* every knob text fits each knob box it is in: PLAY's 130 px (cx_1..3, swing, gate, dyn: 13 characters at 22 px, 0.45 a
 * character) and SHAPE's 151 px (15), over every step and value, on 4 and 8 chords, a busy Walk (two-digit counts), and every
 * Melody: recipe Hook and Approach, classic Hook and Arp, Manual (tools/textfit.py checks the boxes from layout.conf) */
static int knob_chars(const char *key) {
    static const char *const PLAY[] = {"cx_1", "cx_2", "cx_3", "swing", "gate", "dyn"};
    if ((!strncmp(key, "k_b", 3) || !strncmp(key, "k_j", 3)) && key[3] >= '2' && key[3] <= '5' && !key[4]) return 14;   /* 0.19: the BASS
                                                                                                * ring's boxes (CHORDS's); 0.20 MELODY's */
    for (int i = 0; i < 6; i++)
        if (!strcmp(key, PLAY[i])) return 13;
    return 15;
}
static void test_13_text_widths(void) {
    static const char *const MELS[5][2] = {{"mty_4", NULL}, {"mty_7", NULL}, {"style_3=0", "style_3=1"}, {"style_3=0", "style_3=2"},
                                           {"style_3=0", NULL}};
    const mpc_engine_t *en = mpc_engine();
    void *x = en->create(NULL);
    char b[64], worst[96] = "";
    int over = 0;
    en->set_param(x, "style_2", "3");
    eng_set(en, x, "cx_2", 100);
    eng_set(en, x, "length", 3);
    for (int prog = 0; prog <= 15; prog += 15)
        for (int m = 0; m < 5; m++) {
            eng_set(en, x, "prog", prog);
            for (int k = 0; k < 2 && MELS[m][k]; k++)
                if (MELS[m][k][0] == 'm') mel_type_tap(en, x, atoi(MELS[m][k] + 4) - 1);
                else en->set_param(x, "style_3", MELS[m][k] + 8);
            for (int i = 0; i < NPARAMS; i++) {   /* cx_3 comes before the Melody knobs: swept on the classic lane first */
                if (!PARAMS[i].dynamic_display) continue;
                int n = PARAMS[i].nopts ? PARAMS[i].nopts : 101;
                for (int v = 0; v < n; v++) {
                    eng_set(en, x, PARAMS[i].key, v);
                    eng_disp(en, x, PARAMS[i].key, b);
                    if (theory_text_width(b) > knob_chars(PARAMS[i].key))
                        over++, snprintf(worst, sizeof worst, "%s '%s'", PARAMS[i].key, b);
                }
            }
        }
    CHECK(!over, "every knob text fits each box it is in: 13 characters on PLAY, 15 on SHAPE, 14 on the BASS ring (%d over; %s)", over, worst);
    en->destroy(x);
}

/* fix round 1: a host restoring every k_* param's params.json default after a load (a 0.12 project has no values for them)
 * leaves the project as loaded: knobs off their default steps, a classic Arp kept classic. After the guard's 64 blocks a
 * default set applies. The engine's default table agrees with params.json. */
static void test_13_load_guard(void) {
    static char s1[SEQ_STATE_MAX], s2[SEQ_STATE_MAX];
    static const char *const OLDK[5] = {"harmony", "ccol", "cspr", "breg", "mreg"};
    static const int OLDV[5] = {70, 40, 80, 0, 85};
    void *chunk = NULL;
    int ok = 1;
    for (int t = 0; t < NKOPT; t++) {   /* KDEFAULT == params.json's defaults: a host restoring them is what the guard drops */
        const char *k = kopt(t);   /* 0.17: knobs 2-5 too; 0.18: the slots k_s2..5 */
        const param_t *p = &PARAMS[idx(k)];
        const mpc_engine_t *en = mpc_engine();
        void *x = en->create(NULL);
        en->set_param(x, "state", "csq2|gv=1|k=4|s=1|A.len=4|A.cl=16|A.h=30,1|A.prog=0526|A.voi=1|ch=1,2,3|A1=0:|A1.g=4,1,30|A2=0:|A2.g=4,1,30|A3=0:|A3.g=8,1,30|A4=0:");
        int def = p->nopts ? (int)lroundf(p->def * (p->nopts - 1)) : (int)lroundf(p->def * 100), other = !p->nopts ? 50 : def ? 0 : 1;   /* 0.22
                                                                                                                             * k_s1, k_b1: numbers */
        static char before[SEQ_STATE_MAX], after[SEQ_STATE_MAX];
        en->get_param(x, "state", before, sizeof before);
        eng_set(en, x, k, def);     /* the default: dropped, the loaded state stays as it is */
        en->get_param(x, "state", after, sizeof after);
        ok &= !strcmp(before, after);
        eng_set(en, x, k, other);   /* another step: applies (k_col, retired in 0.17: never) */
        int got = eng_num(en, x, k), want = t == 1 || (t >= 3 && t <= 6) ? def : other;   /* 0.19: k_bmov..k_breg retired on a DRAWN Bass */
        if (!strcmp(k, "k_s1") || !strcmp(k, "k_b1")) want = 10;   /* 0.22 on JAM with no block: a jump starts HOUSE level 1 (reads 10) */
        if (!strcmp(k, "k_s2") || !strcmp(k, "k_b2")) want = 1;   /* 0.22 on JAM DENSITY's 5 steps on 6 options: from AS DRAWN (3) one step
                                                                    * toward 0, THIN (R4: 1) */
        if (!strcmp(k, "k_s5")) want = 5;   /* 0.22 on JAM VARIATION's 4 steps on 17 options: BAR 4 reads 5 (R4) */
        if (!strcmp(k, "k_j2")) want = 1;   /* 0.21 DENSITY's 5 steps on 6 options: from AS DRAWN (3) one step toward 0, THIN, reads 1 (R4);
                                             * REGISTER (k_j4, 2 -> 0) and TIME (k_j8, 2 -> 0: NORMAL to HALF) land on 0 */
        if (got != want) printf("     %s: %d, want %d\n", k, got, want);
        ok &= got == want;
        en->destroy(x);
    }
    CHECK(ok, "right after a load a k_* set of its default is dropped, another step applies");
    for (int sc = 0; sc < 2; sc++) {   /* 0: the five knobs off their defaults, a recipe Melody; 1: the four and a classic Arp */
        AEffect *a = start_from(old_state()), *f = start_from(old_state());   /* 0.19: its Bass DRAWN, as the load left it */
        for (int i = 0; i < 5; i++)
            if (sc == 0 || i < 4) a->setP(a, idx(OLDK[i]), OLDV[i] / 100.0f);
        if (sc == 1) a->setP(a, idx("style_3"), 1.0f);   /* Arp: a classic lane (0.10's ARP) */
        a->setP(a, idx("k_vcol"), 3 / 5.0f);              /* 0.17: COLOUR 9th, off its default */
        run(a, 8, 0);
        intptr_t n = a->d(a, effGetChunk, 0, 0, &chunk, 0);
        snprintf(s1, sizeof s1, "%.*s", (int)n, (const char *)chunk);
        f->d(f, effSetChunk, 0, (int)strlen(s1) + 1, s1, 0);
        for (int t = 0; t < NKOPT; t++) {   /* the host restores every new param's default */
            const char *k = kopt(t);
            const param_t *p = &PARAMS[idx(k)];
            f->setP(f, idx(k), p->def);
            run(f, 2, 0);
        }
        n = f->d(f, effGetChunk, 0, 0, &chunk, 0);
        snprintf(s2, sizeof s2, "%.*s", (int)n, (const char *)chunk);
        int same = !strcmp(s1, s2) && (sc == 0 || !strstr(s2, "A3.mr="));
        if (!same) printf("     before %s\n     after  %s\n", s1, s2);
        CHECK(same, "%s: every k_* restored to its default after the load, the project re-saves byte-identical",
              sc ? "a classic Arp and harmony 70, ccol 40, cspr 80, breg 0 (no A3.mr=)" : "harmony 70, ccol 40, cspr 80, breg 0, mreg 85");
        run(f, 70, 0);   /* past the guard's 64 blocks: a default set is the user's */
        f->setP(f, idx("k_harm"), 0.0f);   /* Common */
        f->setP(f, idx("k_breg"), 0.5f);   /* Natural */
        run(f, 2, 0);
        CHECK(lroundf(f->getP(f, idx("harmony")) * 100) == 0 && lroundf(f->getP(f, idx("breg")) * 100) == 50,
              "after the window a default step set applies (harmony 0, breg 50)");
        a->d(a, effClose, 0, 0, NULL, 0);
        f->d(f, effClose, 0, 0, NULL, 0);
    }
}

/* fix round 1: Q-Link from an off-step value on every banded knob lands on the adjacent step (its value) and keeps going */
static void test_13_qlink_off_step(void) {
    static const struct { const char *old, *knob; int v, dir, want_step, want_v; } T[] = {
        {"harmony", "k_harm", 30, 1, 1, 34}, {"cspr", "k_spr", 79, 1, 2, 80}, {"cspr", "k_spr", 79, -1, 0, 50},
        {"mten", "k_mten", 66, 1, 1, 80}, {"mreg", "k_mreg", 26, 1, 2, 85}, {"mreg", "k_mreg", 26, -1, 0, 15},
        {"mrng", "k_mrng", 33, 1, 1, 50}, {"mlea", "k_mlea", 66, 1, 1, 80}, {"msyn", "k_msyn", 59, 1, 1, 70},
        {"mans", "k_mans", 66, 1, 2, 85}, {"mans", "k_mans", 34, -1, 0, 20}};
    int ok = 1;
    for (unsigned t = 0; t < sizeof T / sizeof T[0]; t++) {
        AEffect *e = old_start();
        int i = idx(T[t].knob), n = PARAMS[i].nopts;
        e->setP(e, idx(T[t].old), T[t].v / 100.0f);
        run(e, 2, 0);
        for (int ev = 0; ev < 3; ev++) {   /* one step's worth of Q-Link events (qlink_ticks 3) */
            e->setP(e, i, e->getP(e, i) + T[t].dir / 128.0f);
            run(e, 1, 0);
        }
        int s = (int)lroundf(e->getP(e, i) * (n - 1)), v = (int)lroundf(e->getP(e, idx(T[t].old)) * 100), more = 1;
        if (s + T[t].dir >= 0 && s + T[t].dir < n) {   /* and on: it never sticks */
            for (int ev = 0; ev < 3; ev++) {
                e->setP(e, i, e->getP(e, i) + T[t].dir / 128.0f);
                run(e, 1, 0);
            }
            more = (int)lroundf(e->getP(e, i) * (n - 1)) == s + T[t].dir;
        }
        if (s != T[t].want_step || v != T[t].want_v || !more)
            printf("     %s %d %+d: step %d (want %d), %s %d (want %d), on %d\n", T[t].knob, T[t].v, T[t].dir, s, T[t].want_step, T[t].old, v,
                   T[t].want_v, more);
        ok &= s == T[t].want_step && v == T[t].want_v && more;
        e->d(e, effClose, 0, 0, NULL, 0);
    }
    CHECK(ok, "Q-Link from off-step values (harmony 30, cspr 79, mten 66, mreg 26, ...) moves to the adjacent step and on");
}

/* 0.14 FIX by bar: the params appended after cshtag, in order, flagged; fs_/fsl_ unpolled; every new key answers */
static void test_14_keys(void) {
    static const char *const BAD[] = {"fbs_0", "fbs_5", "fbar_0", "fbar_17", "fbar_", "fbs_1x", "cfixnote_on", "cbar_on", "cbarx",
                                      "cfview_display_on", "cfviewx", "fbar_1_onx"};
    char key[16], b[64];
    const mpc_engine_t *en = mpc_engine();
    void *x = en->create(NULL);
    en->set_param(x, "state", old_state());   /* the pre-VST-12 start: E minor */
    int k0 = idx("cshtag") + 1, ok = k0 == 476 && idx("cbar") == k0 && PARAMS[k0].nopts == 5 && !PARAMS[k0].string_display;   /* 0.22 + Jam */
    for (int i = 1; i <= 4; i++) {
        snprintf(key, sizeof key, "fbs_%d", i);
        ok &= idx(key) == k0 + i && PARAMS[idx(key)].string_display && PARAMS[idx(key)].no_poll;   /* 0.24 FIX retired: unpolled */
    }
    for (int i = 1; i <= 16; i++) {
        snprintf(key, sizeof key, "fbar_%d", i);
        ok &= idx(key) == k0 + 4 + i && PARAMS[idx(key)].string_display && PARAMS[idx(key)].no_poll;
    }
    int v = idx("cfview");
    ok &= idx("cfixnote") == k0 + 21 && PARAMS[k0 + 21].string_display && PARAMS[k0 + 21].no_poll && v == k0 + 22 &&
          PARAMS[v].nopts == 16 && PARAMS[v].dynamic_display && idx("cfview_prev") == v + 1 && idx("cfview_next") == v + 2 &&
          PARAMS[v + 1].step_target == v && PARAMS[v + 1].step_delta < 0 && PARAMS[v + 2].step_target == v && PARAMS[v + 2].step_delta > 0;
    CHECK(ok && idx("init") == 501, "0.14 params appended after cshtag: cbar, fbs_1..4, fbar_1..16, cfixnote (0.24 unpolled), cfview "
          "(dynamic_display) and its arrows (%d params)", NPARAMS);
    int polled = 0;
    ok = 1;
    for (int i = 0; i < NPARAMS; i++) polled += PARAMS[i].string_display && !PARAMS[i].no_poll;
    for (int i = 1; i <= 8; i++) {
        snprintf(key, sizeof key, "fs_%d", i);
        ok &= PARAMS[idx(key)].no_poll;
    }
    for (int i = 1; i <= 4; i++) {
        snprintf(key, sizeof key, "fsl_%d", i);
        ok &= PARAMS[idx(key)].no_poll;
    }
    CHECK(ok && polled == 784, "fs_1..8 and fsl_1..4 are unpolled; %d polled cells (0.13: 359; 0.14: 368; VST-12: +15 phrasing, -2 mph_; "
          "0.16: +38 FIX by bar; 0.17: +132 the CHORDS page, -37 IDEAS and SHAPE; 0.18: +61 the RHYTHM page, -11 crh_, cnr_ and new_1, "
          "+16 rcp_; 0.19: +151 the BASS page and its KEYS (ucw, never placed, unpolled), -92 BASS IDEAS, SHAPE and FIX A NOTE, +81 the "
          "BASS RHYTHM page; 0.20: +101 the MELODY JAM page and its KEYS (jnow, jnext, jmsg unpolled), -124 MELODY RECIPE, IDEAS, SHAPE, "
          "FIX NOTE, phrasing and FIX by bar; +102 the PHRASE page, its picker and bar editor (wfmt, want, wsum, wpnt, wett, went, wmsg "
          "unpolled); 0.22: +72 the CHORDS and BASS JAM pages' blocks, bars, SWITCH AT and mode cells (their readouts and meters unpolled); "
          "0.24: +15 OCTAVE, GLOBAL's NAMES and the sound pages' bars and EDIT BARS, -113 the FIX mode cell, NAMES, the CHORDS strip, paging, "
          "picker, FIX cells and old centre texts, the BASS strip, paging, editor and old centre texts; Task 7 +137 the PHRASE pages' cells that light "
          "and their RHYTHM fields: the strips, LOCK WITH, ANTICIPATE, paints, steps, pickers, COPY TO...'s bars, -126 the RHYTHM pages' cells "
          "they replace: rst_, rpt_, rfl_, csr_, rcb_, rcp_, rtt and their BASS RHYTHM twins, ysc_ too)", polled);
    static const char *const TAPK[] = {"fbs_", "fbar_", "fs_", "fsl_"};
    static const int TAPN[] = {4, 16, 8, 4};
    ok = 1;
    for (int t = 0; t < 4; t++)
        for (int i = 1; i <= TAPN[t]; i++) {
            snprintf(key, sizeof key, "%s%d", TAPK[t], i);
            int label = en->get_param(x, key, b, sizeof b) > 0;
            snprintf(key, sizeof key, "%s%d_on", TAPK[t], i);
            int on = en->get_param(x, key, b, sizeof b) > 0 && (!strcmp(b, "0") || !strcmp(b, "1"));
            if (!label || !on) printf("     %s%d: label %d, _on %d\n", TAPK[t], i, label, on);
            ok &= label && on;
        }
    ok &= en->get_param(x, "cfixnote", b, sizeof b) > 0 && en->get_param(x, "cbar", b, sizeof b) > 0 && en->get_param(x, "cfview", b, sizeof b) > 0;
    eng_disp(en, x, "cfview", b);
    CHECK(ok && !strcmp(b, "BAR 1"), "fbs_, fbar_ (and the old fs_, fsl_) answer label and _on; cfixnote, cbar, cfview answer; cfview_display "
          "'%s'", b);
    ok = 1;
    for (int i = 0; i < (int)(sizeof BAD / sizeof BAD[0]); i++) {
        int got = en->get_param(x, BAD[i], b, sizeof b);
        if (got > 0) printf("     %s answered '%s'\n", BAD[i], b);
        ok &= got <= 0;
    }
    CHECK(ok, "unknown 0.14 keys and suffixes are rejected");
    en->destroy(x);
}

