/* 0.15 INIT: a new instance starts at INIT; MPC's PRESET menu lists Current and Init. The program reads Init until the next
 * edit, then Current, so every pick of Init after an edit resets; a project's state still loads over INIT */
static void test_15_init(void) {
    enum { effSetProgram = 2, effGetProgram = 3, effGetProgramNameIndexed = 29 };
    char t[128], n0[32] = "", n1[32] = "", n2[32] = "x";
    AEffect *e = VSTPluginMain(host), *f = VSTPluginMain(host);
    const param_t *pi = &PARAMS[idx("init")];
    CHECK(idx("init") == idx("cfview_next") + 1 && pi->nopts == 2 + PRESETS_COUNT && pi->no_poll,
          "VST-12 appends init (Current, Init, 0.23 the genre presets; unpolled) after 0.14's cfview_next (%d params)", NPARAMS);
    display(e, "title", t);
    CHECK(!strcmp(t, "C MAJOR" DOT "1-5-6-4 Pop"), "a new instance starts at INIT ('%s')", t);
    CHECK(e->np == 2 + PRESETS_COUNT && e->d(e, effGetProgramNameIndexed, 0, 0, n0, 0) && e->d(e, effGetProgramNameIndexed, 1, 0, n1, 0) &&
          !e->d(e, effGetProgramNameIndexed, 2 + PRESETS_COUNT, 0, n2, 0) && !strcmp(n0, "Current") && !strcmp(n1, "Init"),
          "the PRESET menu lists Current and Init (%d: '%s', '%s')", e->np, n0, n1);
    int ok = e->d(e, effGetProgram, 0, 0, NULL, 0) == 1;   /* a new instance is at Init */
    for (int r = 0; r < 2; r++) {   /* twice: a second pick of Init after an edit resets again */
        e->setP(e, idx("key"), 2.0f / 11.0f);   /* D */
        e->setP(e, idx("scale"), 1.0f / 6.0f);  /* Minor */
        run(e, 4, 0);
        display(e, "title", t);
        ok &= !strncmp(t, "D MINOR", 7) && e->d(e, effGetProgram, 0, 0, NULL, 0) == 0;
        e->d(e, effSetProgram, 0, 1, NULL, 0);
        run(e, 4, 0);
        display(e, "title", t);
        ok &= !strcmp(t, "C MAJOR" DOT "1-5-6-4 Pop") && e->d(e, effGetProgram, 0, 0, NULL, 0) == 1;
    }
    CHECK(ok, "the program reads Init until an edit, and picking Init resets an edited instance, every time ('%s')", t);
    e->setP(e, idx("key"), 2.0f / 11.0f);
    run(e, 4, 0);
    e->d(e, effSetProgram, 0, 0, NULL, 0);   /* Current: nothing changes */
    display(e, "title", t);
    CHECK(!strncmp(t, "D MAJOR", 7), "picking Current changes nothing ('%s')", t);
    void *chunk = NULL;
    intptr_t n = e->d(e, effGetChunk, 0, 0, &chunk, 0);
    if (n > 0 && chunk) f->d(f, effSetChunk, 0, n, chunk, 0);
    display(f, "title", t);
    CHECK(n > 0 && !strncmp(t, "D MAJOR", 7), "a saved project loads as saved, not as INIT ('%s')", t);
    e->d(e, effClose, 0, 0, NULL, 0);
    f->d(f, effClose, 0, 0, NULL, 0);
}

/* 0.23 the genre presets in MPC's PRESET menu after Init: each loads all 6 parts as a project's state (the channels and FOLLOW stay),
 * reads as the program until an edit, and PLAY's title says what it was made for meanwhile */
static void test_23_presets(void) {
    enum { effSetProgram = 2, effGetProgram = 3, effGetProgramNameIndexed = 29 };
    char t[128], nm[32], ch[3][64];
    AEffect *e = VSTPluginMain(host), *f = VSTPluginMain(host);
    int names = 1, ok;
    void *chunk = NULL;
    intptr_t n;
    for (int i = 0; i < PRESETS_COUNT; i++)
        names &= e->d(e, effGetProgramNameIndexed, 2 + i, 0, nm, 0) && !strcmp(nm, preset_info(i)->name);
    CHECK(names, "programs 2-7 are the presets by name: House 124 .. Disco 118");
    for (int l = 0; l < 3; l++) e->setP(e, idx(l == 0 ? "ch_1" : l == 1 ? "ch_2" : "ch_3"), (4 + l) / 15.0f);   /* channels 5, 6, 7 */
    seq_set_follow(engine_of(e), 0);   /* FOLLOW off */
    ok = !seq_follow(engine_of(e));
    e->d(e, effSetProgram, 0, 2, NULL, 0);
    run(e, 4, 0);
    display(e, "title", t);
    for (int l = 0; l < 3; l++) display(e, l == 0 ? "ch_1" : l == 1 ? "ch_2" : "ch_3", ch[l]);
    n = e->d(e, effGetChunk, 0, 0, &chunk, 0);
    CHECK(n > 0 && chunk && strstr(chunk, "|gn=1") && strstr(chunk, "|A.len=8") && strstr(chunk, "|F.len=4"),
          "House loads: gn=1, the Verse 8 bars, the Outro 4");
    CHECK(!strcmp(t, "HOUSE" DOT "124 BPM" DOT "PIANO, SUB, PLUCK") && e->d(e, effGetProgram, 0, 0, NULL, 0) == 2,
          "it is the program, and PLAY's title says what it was made for ('%s')", t);
    CHECK(!strcmp(ch[0], "5") && !strcmp(ch[1], "6") && !strcmp(ch[2], "7") && ok && !seq_follow(engine_of(e)),
          "the channels (5 6 7) and FOLLOW (off) stay ('%s %s %s')", ch[0], ch[1], ch[2]);
    char *before = strdup(chunk);
    e->d(e, effSetProgram, 0, 2, NULL, 0);   /* MPC re-selecting the current program: the wrapper skips it */
    run(e, 4, 0);
    n = e->d(e, effGetChunk, 0, 0, &chunk, 0);
    CHECK(n > 0 && !strcmp(before, chunk), "picking it again while it is current changes nothing");
    free(before);
    f->d(f, effSetChunk, 0, n, chunk, 0);
    run(f, 4, 0);
    n = f->d(f, effGetChunk, 0, 0, &chunk, 0);
    display(f, "title", t);
    CHECK(n > 0 && strstr(chunk, "|gn=1") && f->d(f, effGetProgram, 0, 0, NULL, 0) == 0 && !strncmp(t, "A MINOR", 7),
          "a project saved with it reloads with gn=1, the menu at Current, the title the key line ('%s')", t);
    e->setP(e, idx("key"), 2.0f / 11.0f);   /* D: an edit */
    run(e, 4, 0);
    display(e, "title", t);
    CHECK(e->d(e, effGetProgram, 0, 0, NULL, 0) == 0 && !strncmp(t, "D MINOR", 7), "an edit leaves the preset: the title is the key line ('%s')", t);
    e->d(e, effSetProgram, 0, 5, NULL, 0);   /* Pop */
    run(e, 4, 0);
    display(e, "title", t);
    CHECK(!strcmp(t, "POP" DOT "110 BPM" DOT "PIANO, BASS, SYNTH LEAD") && seq_key(engine_of(e)) == 7 && seq_scale(engine_of(e)) == SCALE_MAJOR,
          "Pop loads over the edit: G major ('%s')", t);
    ti[3] = 0, run(e, 300, 1);   /* playing */
    e->d(e, effSetProgram, 0, 7, NULL, 0);   /* Disco, mid-play */
    run(e, 300, 1), run(e, 4, 0);
    display(e, "title", t);
    CHECK(!strcmp(t, "DISCO" DOT "118 BPM" DOT "STRINGS, SLAP BASS, BRASS"), "a pick while playing loads ('%s')", t);
    e->d(e, effClose, 0, 0, NULL, 0);
    f->d(f, effClose, 0, 0, NULL, 0);
}

