/* 0.17 the CHORDS page: the params appended after the 0.16 block, in the plan's order (n 0: one param, else prefix_1..n) */
static const struct { const char *key; int n; } P17[] = {
    {"cview", 0}, {"cvm_", 3}, {"k_vcol", 0}, {"k_vinv", 0}, {"k_vspr", 0}, {"k_vstr", 0}, {"cst_", 4}, {"tint_", 4}, {"cpg_", 2},
    {"cpage", 0}, {"cund_", 1}, {"cbtp_", 1}, {"ccount", 0}, {"cfol", 0}, {"cpr_", 3}, {"cvo_", 3}, {"crk_", 1}, {"ccn", 0},
    {"ccd", 0}, {"cdr", 0}, {"cct_", 1}, {"cdrift", 0}, {"ptl", 0}, {"pty_", 5}, {"plk_", 1}, {"pcn_", 1}, {"pdn_", 1},
    {"bpr_", 16}, {"bgn_", 13}, {"bvs_", 4}, {"bvf_", 4}, {"bcn_", 1}, {"bdo_", 1}, {"btl", 0}, {"kyw_", 35}, {"kyb_", 25},
    {"kye_", 2}};

static void test_17_params_appended(void) {
    static const char *const BAD[] = {"cst_0", "cst_5", "cvm_5", "kyw_36", "kyb_26", "kye_3", "bpr_17", "bgn_16", "bvs_5", "pty_6",
                                      "tint_0", "tint_5", "tint_1x", "cviewx", "cdrift_on", "ccount_on", "k_vcolx", "k_vstr_on", "cpr_4",
                                      "bdo_2", "ccn_on", "btlx"};
    static const char *const QUIET[] = {"md_1", "ds_1", "fd_5", "ia_1", "pn_1", "mv_1", "itag", "lnote", "vo_1", "oc_1", "cnp_1", "cshtag",
                                        "k_harm", "k_col", "k_spr", "cstrum", "ptl", "btl", "bvf_1", "bvf_4", "chord_1", "fs_1",
                                        "fbs_1", "fbar_1", "fc_1", "fb_1", "fo_1", "cfixnote", "cnm_1", "cst_1", "ccn", "cpage"};   /* 0.24 FIX,
                                                                                * NAMES, the CHORDS page's strip and old centre: retired */
    static const char *const LOUD[] = {"pt_1", "kyw_1", "kyb_25", "kye_2", "cvm_1", "bpr_16", "ccount", "cfol"};
    static const int VN[4] = {6, 6, 5, 17}, VD[4] = {1, 2, 1, 8};
    const mpc_engine_t *en = mpc_engine();
    void *x = en->create(NULL);
    char key[16], b[64];
    int k = idx("mfn") + 1, ok = idx("mfn") == 554 && idx("cshtag") == 475;
    for (unsigned t = 0; t < sizeof P17 / sizeof P17[0]; t++)
        for (int i = P17[t].n ? 1 : 0; i <= P17[t].n; i++) {
            if (P17[t].n) snprintf(key, sizeof key, "%s%d", P17[t].key, i);
            else snprintf(key, sizeof key, "%s", P17[t].key);
            if (k >= NPARAMS || strcmp(PARAMS[k].key, key)) {
                printf("     %d: %s, want %s\n", k, k < NPARAMS ? PARAMS[k].key : "-", key);
                ok = 0;
            }
            k++;
        }
    for (int i = 14; i <= 15; i++, k++) {   /* Task 9: the skin's 5-a-row genre list's two blank cells, after kye_2 */
        snprintf(key, sizeof key, "bgn_%d", i);
        if (k >= NPARAMS || strcmp(PARAMS[k].key, key)) ok = 0;
    }
    CHECK(ok && k < NPARAMS && !strcmp(PARAMS[k].key, "k_s2"), "0.17 params appended after mfn (the 0.16 params keep their indices) in "
          "the plan's order, then bgn_14..15, then 0.18's (%d params)", NPARAMS);
    ok = PARAMS[idx("cview")].nopts == 10 && PARAMS[idx("cdrift")].nopts == 4 && !PARAMS[idx("cview")].string_display;   /* 0.22 + Jam */
    for (int i = 0; i < 4; i++) {
        const param_t *p = &PARAMS[idx(VK17[i])];
        ok &= p->nopts == VN[i] && p->qlink_ticks == 3 && p->dynamic_display && lroundf(p->def * (p->nopts - 1)) == VD[i];
    }
    for (int i = 1; i <= 4; i++) {
        snprintf(key, sizeof key, "tint_%d", i);
        const param_t *p = &PARAMS[idx(key)];
        ok &= !p->string_display && !p->nopts && p->min == 0 && p->max == 5 && p->def == 1.0f;
    }
    CHECK(ok, "cview and cdrift options; k_vcol..k_vstr stepped (6, 6, 5, 17; Pop Piano's 0), qlink_ticks 3, dynamic_display; tint_ 0..5");
    ok = 1;
    for (unsigned i = 0; i < sizeof QUIET / sizeof QUIET[0]; i++) ok &= PARAMS[idx(QUIET[i])].no_poll;
    for (unsigned i = 0; i < sizeof LOUD / sizeof LOUD[0]; i++) ok &= !PARAMS[idx(LOUD[i])].no_poll && PARAMS[idx(LOUD[i])].string_display;
    CHECK(ok, "IDEAS and SHAPE's cells and readouts unpolled (still answering), the tap-only readouts too (0.24 FIX, NAMES and the strip "
          "too); the page polled");
    ok = 1;
    for (int i = idx("cview"); i < NPARAMS; i++) {
        const param_t *p = &PARAMS[i];
        int got = en->get_param(x, p->key, b, sizeof b), cell = strchr(p->key, '_') && p->string_display;
        if (cell) {
            snprintf(key, sizeof key, "%s_on", p->key);
            cell = en->get_param(x, key, b, sizeof b) > 0 && (!strcmp(b, "0") || !strcmp(b, "1"));
        }
        if (got <= 0 || (strchr(p->key, '_') && p->string_display && !cell)) printf("     %s: %d\n", p->key, got);
        ok &= got > 0 && (!strchr(p->key, '_') || !p->string_display || cell);
    }
    for (unsigned i = 0; i < sizeof BAD / sizeof BAD[0]; i++) {
        int got = en->get_param(x, BAD[i], b, sizeof b);
        if (got > 0) printf("     %s answered '%s'\n", BAD[i], b);
        ok &= got <= 0;
    }
    CHECK(ok, "every 0.17 key answers (cells their _on too); unknown keys and suffixes are rejected");
    en->destroy(x);
}

/* the CHORDS page's views: cvm_ switch them (FIX's layout follows), a centre or strip tap opens the picker, DONE and CANCEL end it. 0.24: FIX
 * and the picker are retired: cvm_3 does nothing, the centre opens PHRASE (the Rhythm view), a strip tap does nothing */
static void test_17_cview_taps(void) {
    char b[64], c[64];
    AEffect *e = VSTPluginMain(host);   /* INIT: C major, Pop (C G Am F), 4 bars of 1-bar chords */
    tap(e, "cvm_1", 1);   /* 0.22: a new instance opens on JAM (test_22_open_on_jam) */
    display(e, "cview", b);
    CHECK(!strcmp(b, "Chords") && lit_one(e, "cvm_", 3, 1), "cvm_1 shows the Chords view, cvm_1 lit (cview '%s')", b);
    tap(e, "cvm_3", 1);
    run(e, 40, 0);   /* the wrapper reads display_rev every 100 ms */
    display(e, "cview", b);
    display(e, "cbar", c);
    CHECK(!strcmp(b, "Chords") && lit_one(e, "cvm_", 3, 1) && !strcmp(c, "-"), "0.24 cvm_3 (FIX, retired) does nothing (cview '%s', cbar '%s')",
          b, c);
    tap(e, "cvm_2", 1);
    display(e, "cview", b);
    display(e, "cbar", c);
    CHECK(!strcmp(b, "Rhythm") && lit_one(e, "cvm_", 3, 2) && !strcmp(c, "-"), "cvm_2: Rhythm (0.24 PHRASE), off FIX (cbar '%s')", c);
    tap(e, "cvm_1", 1);
    display(e, "cview", b);
    CHECK(!strcmp(b, "Chords") && lit_one(e, "cvm_", 3, 1), "cvm_1: Chords ('%s')", b);
    display(e, "ccn", b);
    display(e, "ccd", c);
    CHECK(!strcmp(b, "C") && !strcmp(c, "I" DOT "C E G"), "the old centre still answers: the chord and its numeral and notes ('%s', '%s')", b, c);
    tap(e, "cct_1", 1);
    display(e, "cview", b);
    display(e, "ptl", c);
    CHECK(!strcmp(b, "Rhythm") && lit_one(e, "cvm_", 3, 2) && !strcmp(c, " "),
          "0.24 cct_1 opens PHRASE (cview '%s'), no picker (ptl '%s')", b, c);
    tap(e, "cvm_1", 1);
    tap(e, "cst_3", 1);
    display(e, "cview", b);
    CHECK(!strcmp(b, "Chords"), "0.24 a strip tap (cst_, retired) opens nothing (cview '%s')", b);
    e->d(e, effClose, 0, 0, NULL, 0);
}

/* knobs 2-5: each step's text (at most 14 characters; STRUM in ms at the host tempo, 120 BPM stopped), the CHORDS fields */
static void test_17_knob_texts(void) {
    static const struct { const char *key; int i; const char *want; } T[] = {
        {"k_vcol", 0, "Power"}, {"k_vcol", 1, "Triad"}, {"k_vcol", 2, "7th"}, {"k_vcol", 3, "9th"}, {"k_vcol", 4, "11th"},
        {"k_vcol", 5, "13th"}, {"k_vinv", 0, "-2"}, {"k_vinv", 1, "-1"}, {"k_vinv", 2, "Root"}, {"k_vinv", 3, "+1"}, {"k_vinv", 5, "+3"},
        {"k_vspr", 0, "Cluster"}, {"k_vspr", 1, "Close"}, {"k_vspr", 2, "Open"}, {"k_vspr", 3, "Split"}, {"k_vspr", 4, "Wide"},
        {"k_vstr", 8, "Block"}, {"k_vstr", 9, "Up 4 ms"}, {"k_vstr", 13, "Up 20 ms"}, {"k_vstr", 0, "Down 31 ms"}};
    static const int LO[4] = {-1, -2, -1, -8};
    const mpc_engine_t *en = mpc_engine();
    void *x = en->create(NULL);
    seq_t *q = x;
    char b[64], c[64];
    int ok = 1;
    for (unsigned i = 0; i < sizeof T / sizeof T[0]; i++) {
        int k = T[i].key[3] == 'c' ? VK_COL : T[i].key[3] == 'i' ? VK_INV : T[i].key[4] == 'p' ? VK_SPR : VK_STR;
        eng_set(en, x, T[i].key, T[i].i);
        eng_disp(en, x, T[i].key, b);
        int good = !strcmp(b, T[i].want) && theory_text_width(b) <= 14 && eng_num(en, x, T[i].key) == T[i].i &&
                   seq_vknob(q, k) == T[i].i + LO[k];
        if (!good) printf("     %s %d: '%s', want '%s' (core %d)\n", T[i].key, T[i].i, b, T[i].want, seq_vknob(q, k));
        ok &= good;
    }
    CHECK(ok, "%d knob steps: the core's value and the text (Power..13th, -2..+3, Cluster..Wide, Block, Up/Down N ms)",
          (int)(sizeof T / sizeof T[0]));
    eng_set(en, x, "k_vstr", 16);   /* Up 8 */
    for (int k = 0; k < 8; k++) en->song_pos(x, k * 0.01, 160.0, 1, 128);
    eng_disp(en, x, "k_vstr", b);
    eng_set(en, x, "k_vstr", 0);
    eng_disp(en, x, "k_vstr", c);
    CHECK(!strcmp(b, "Up 23 ms") && !strcmp(c, "Down 23 ms"), "at 160 BPM: '%s', '%s'", b, c);
    for (int k = 0; k < 4; k++) en->song_pos(x, 0, 160.0, 0, 128);
    eng_set(en, x, "k_vcol", 2);
    eng_disp(en, x, "ccol", b);
    eng_disp(en, x, "k_col", c);
    CHECK(!strcmp(b, "7th") && !strcmp(c, "7th"), "the retired ccol and k_col read the COLOUR knob's level ('%s', '%s')", b, c);
    eng_set(en, x, "k_col", 9);   /* retired: no-op */
    CHECK(seq_vknob(q, VK_COL) == 1 && eng_num(en, x, "k_col") == 0, "a k_col set changes nothing");
    en->get_param(x, "cvo_2", b, sizeof b);
    CHECK(!strcmp(b, "As Written (edited)"), "the VOICING field: INIT's style, edited by the knobs ('%s')", b);
    en->set_param(x, "crk_1", "1");
    en->get_param(x, "cvo_2", b, sizeof b);
    ok = seq_vknob(q, VK_COL) == 0 && seq_vknob(q, VK_INV) == 0 && seq_vknob(q, VK_SPR) == 0 && seq_vknob(q, VK_STR) == 0;
    CHECK(ok && !strcmp(b, "As Written"), "RESET KNOBS: the four knobs to 0 ('%s')", b);
    en_press(en, x, "cvo_3");
    en->get_param(x, "cvo_2", b, sizeof b);
    en_press(en, x, "cvo_1");
    en_press(en, x, "cvo_1");
    en->get_param(x, "cvo_2", c, sizeof c);
    CHECK(!strcmp(b, "Cinematic") && !strcmp(c, "Ballad") && seq_voicing_style(q) == 47, "the VOICING arrows step the styles ('%s', '%s')", b, c);
    en->get_param(x, "cpr_2", b, sizeof b);
    en_press(en, x, "cpr_3");
    en->get_param(x, "cpr_2", c, sizeof c);
    CHECK(!strcmp(b, "Pop" DOT "C G Am F") && !strcmp(c, "Sad Pop" DOT "Am F C G"), "the PROGRESSION field and its arrows ('%s', '%s')", b, c);
    en_press(en, x, "cpr_1");
    seq_set_slot(q, 0, 1, 0, seq_slot_colour(q, 0));   /* slot 1 to ii, unlocked: no preset matches (0.24 the picker is retired: the core) */
    seq_toggle_slot_lock(q, 0);
    en->set_param(x, "cvm_1", "1");   /* a set: the labels are made again */
    en->get_param(x, "cpr_2", b, sizeof b);
    CHECK(!strcmp(b, "Custom"), "edited by hand: Custom ('%s')", b);
    /* every field and tile fits: the progressions (22 characters) at every key and scale, the styles (edited, 22), names 14 */
    int longest = 0, longest_style = 0, longest_name = 0;
    for (int key = 0; key < 12; key++)
        for (int sc = 0; sc < SCALE_COUNT; sc++) {
            eng_set(en, x, "key", key);
            eng_set(en, x, "scale", sc);
            for (int i = 1; i <= 16; i++) {
                snprintf(c, sizeof c, "bpr_%d", i);
                en->get_param(x, c, b, sizeof b);
                if (theory_text_width(b) > longest) longest = theory_text_width(b);
            }
        }
    for (int i = 0; i < VOICING_NSTYLES; i++) {
        seq_set_voicing_style(q, i);
        seq_set_vknob(q, VK_INV, 3);   /* edited */
        en->set_param(x, "panic", "0");   /* any set: the caches */
        en->get_param(x, "cvo_2", b, sizeof b);
        if (theory_text_width(b) > longest_style) longest_style = theory_text_width(b);
        if ((int)strlen(VOICING_STYLES[i].name) > longest_name) longest_name = (int)strlen(VOICING_STYLES[i].name);
        if ((int)strlen(VOICING_STYLES[i].genre) > longest_name) longest_name = (int)strlen(VOICING_STYLES[i].genre);
    }
    CHECK(longest <= 19 && longest_style <= 22 && longest_name <= 14, "progression tiles at most 19 characters (%d, BPR_CHARS), the VOICING "
          "field 22 (%d), style and genre names 14 (%d)", longest, longest_style, longest_name);
    char n[64];
    en->get_param(x, "cct_1", b, sizeof b);
    en->get_param(x, "ccn", n, sizeof n);
    en->get_param(x, "bgn_14", c, sizeof c);
    int blank = !strcmp(c, " ");
    en->get_param(x, "bgn_15_on", c, sizeof c);
    CHECK(!strcmp(b, n) && strcmp(b, " ") && blank && !strcmp(c, "0"),
          "cct_1 reads the centre chord ('%s', ccn '%s'); bgn_14..15 are blank and never lit", b, n);
    en->destroy(x);
}

