/* What a touch can change: the saved state, the undo depth and what the page shows (cell's lit state too). 0.24.1 PHRASE's cells (the
 * RHYTHM page's are retired) */
static void screen_of(AEffect *e, const char *key, char *out, int n) {
    static const char *const SHOWN[] = {"cview", "rmsg", "cqtt", "cqfl", "cqf_2", "cqe_3", "cqctl", "cqcn", "cqx_4", "cqx_6", "cpr_2",
                                        "cvo_2", "ptl", "btl", "cqpage", "cqs_1", "cqs_2", "cqs_3", "cqs_4", "cqc_3", "cqn_1"};
    void *chunk = NULL;
    char b[64];
    intptr_t len = e->d(e, effGetChunk, 0, 0, &chunk, 0);
    unsigned h = 2166136261u;
    for (intptr_t i = 0; chunk && i < len; i++) h = (h ^ ((unsigned char *)chunk)[i]) * 16777619u;
    int k = snprintf(out, n, "state %08x, %s lit %d", h, key, lit(e, key));
    for (size_t i = 0; i < sizeof SHOWN / sizeof SHOWN[0] && k < n; i++) {
        display(e, SHOWN[i], b);
        k += snprintf(out + k, n - k, ", %s '%s'", SHOWN[i], b);
    }
}

static void at_rhythm(AEffect *e) { tap(e, "cvm_2", 1); }
static void at_bar(AEffect *e) { tap(e, "cjp_2", 1); }   /* bar 2 open on RHYTHM (0.24 PHRASE: the JAM bar cell; the strip, cst_, is retired) */
static void at_copy(AEffect *e) { at_bar(e); tap(e, "cqp_7", 1); tap(e, "cqc_3", 1); }   /* COPY TO..., bar 3 picked (0.24.1 PHRASE's) */
static void at_chords(AEffect *e) { (void)e; }
static void at_prog(AEffect *e) { tap(e, "cpr_2", 1); }   /* the PROGRESSIONS browser */
static void at_voice(AEffect *e) { tap(e, "cvo_2", 1); }   /* the VOICING browser */

/* 0.18 device bug, second round (the Force's tap log: one 350 ms touch on LOCK sent 1 on the press and 1 again on the release,
 * 400 ms later, both acting): an image button cell latches. The press's 1 acts and lights it, so MPC holds 1 and the release's
 * toggle sends 0, which clears the latch and does nothing; held 350 or 1200 ms it acts once; a quick touch after a touch acts
 * again; a hold past 1.5 s unlatches (unlit, 0 reported) and the next 1 acts; a 1 while latched does nothing. 0.24.1 on PHRASE's
 * image buttons (the RHYTHM page's LOCK, field and COPY TO... are retired): its RHYTHM field and COPY TO...'s COPY toggle and GO */
static void test_18_buttons_latch(void) {
    static const struct { void (*at)(AEffect *); const char *where, *keys[5]; } CASES[] = {
        {at_bar, "a bar open", {"cqf_1", "cqf_3", NULL}},
        {at_rhythm, "RHYTHM, no bar open", {"cqf_1", "cqf_3", NULL}},
        {at_copy, "COPY TO...", {"cqx_4", "cqx_6", NULL}},
        {at_chords, "CHORDS", {"cpr_1", "cpr_3", "cvo_1", "cvo_3", NULL}},
        {at_prog, "PROGRESSIONS", {"cpr_1", "cpr_3", NULL}},
        {at_voice, "VOICING", {"cvo_1", "cvo_3", NULL}}};
    static const int HOLDS[] = {121, 414};   /* blocks: 350 ms (the remote addin's touch) and 1200 ms */
    static char one_s[4096], two_s[4096];
    char a[64], b[64], c[64];
    int ok = 1, quiet = 1, n = 0;
    for (size_t t = 0; t < sizeof CASES / sizeof CASES[0]; t++)
        for (int k = 0; k < 5 && CASES[t].keys[k]; k++)
            for (size_t h = 0; h < sizeof HOLDS / sizeof HOLDS[0]; h++, n++) {
                const char *key = CASES[t].keys[k];
                AEffect *one = VSTPluginMain(host), *two = VSTPluginMain(host);
                CASES[t].at(one);
                CASES[t].at(two);
                tap(one, key, 1);   /* a quick touch: press, release 23 ms later */
                quiet &= device_press(two, key, HOLDS[h]) == 0;
                screen_of(one, key, one_s, sizeof one_s);
                screen_of(two, key, two_s, sizeof two_s);
                if (strcmp(one_s, two_s))
                    printf("     %s, %s, held %d blocks:\n       quick  %s\n       held   %s\n", CASES[t].where, key, HOLDS[h], one_s, two_s),
                        ok = 0;
                one->d(one, effClose, 0, 0, NULL, 0);
                two->d(two, effClose, 0, 0, NULL, 0);
            }
    CHECK(quiet, "while held the wrapper reports nothing to MPC (the latch keeps its 1, so the release sends 0)");
    CHECK(ok, "each of %d touches held 350 or 1200 ms does what a quick touch does (acts once)", n);

    AEffect *e = VSTPluginMain(host);   /* on >, polled as rac_ was (COPY TO...'s buttons, unpolled, report nothing) */
    at_rhythm(e);
    display(e, "cqf_2", a);
    e->setP(e, idx("cqf_3"), 1.0f);   /* the press */
    run(e, 121, 0);
    display(e, "cqf_2", b);
    CHECK(lit(e, "cqf_3") && strcmp(a, b), "> pressed: the next rhythm ('%s' to '%s') and the cell lit while held (its amber plate)", a, b);
    e->setP(e, idx("cqf_3"), 0.0f);   /* the release, 350 ms later */
    run(e, 8, 0);
    display(e, "cqf_2", c);
    CHECK(!lit(e, "cqf_3") && !strcmp(b, c), "released: no second step, unlit ('%s')", c);
    device_press(e, "cqf_3", 414);
    display(e, "cqf_2", a);
    CHECK(strcmp(a, c), "the next touch, held 1.2 s, steps once more ('%s')", a);
    int i = idx("cqf_3");
    e->setP(e, i, 1.0f);   /* a hold whose release never comes */
    run(e, 500, 0);
    int held = lit(e, "cqf_3");
    long was = automated[i];
    run(e, 30, 0);
    display(e, "cqf_2", b);
    CHECK(held && !lit(e, "cqf_3") && automated[i] > was && reported[i] < 0.5f && strcmp(a, b),
          "a hold with no release: lit at 1.45 s, unlatched by 1.54 s (0 reported to MPC), stepped once ('%s')", b);
    e->setP(e, i, 1.0f);   /* MPC holds 0 again: the next touch's 1 */
    run(e, 8, 0);
    e->setP(e, i, 0.0f);
    run(e, 8, 0);
    display(e, "cqf_2", c);
    CHECK(strcmp(b, c), "and the next press acts: the next rhythm ('%s')", c);
    e->d(e, effClose, 0, 0, NULL, 0);

    AEffect *one = VSTPluginMain(host), *two = VSTPluginMain(host);   /* quick touches on >, one after another: a step each */
    at_rhythm(one);
    at_rhythm(two);
    display(one, "cqf_2", a);
    device_press(one, "cqf_3", 8);
    device_press(one, "cqf_3", 8);
    display(one, "cqf_2", b);
    tap(two, "cqf_3", 1);
    display(two, "cqf_2", c);
    int step1 = strcmp(c, a) && strcmp(c, b);
    tap(two, "cqf_3", 1);
    display(two, "cqf_2", c);
    CHECK(step1 && strcmp(a, b) && !strcmp(b, c), "two quick touches on > step two rhythms ('%s' to '%s', '%s')", a, b, c);
    one->d(one, effClose, 0, 0, NULL, 0);
    two->d(two, effClose, 0, 0, NULL, 0);

    const mpc_engine_t *en = mpc_engine();   /* on the engine: a 1 while latched does nothing; after the 0 the next 1 acts */
    void *x = en->create(NULL);
    en->set_param(x, "cvm_2", "1");
    en->set_param(x, "cqf_3", "1");
    en->get_param(x, "cqf_3_on", c, sizeof c);
    en->get_param(x, "cqf_2", a, sizeof a);
    en->set_param(x, "cqf_3", "1");
    en->get_param(x, "cqf_2", b, sizeof b);
    CHECK(!strcmp(a, b) && !strcmp(c, "1"), "a 1 while latched (lit '%s') does nothing: one step ('%s')", c, b);
    en->set_param(x, "cqf_3", "0");
    en->get_param(x, "cqf_3_on", c, sizeof c);
    en->set_param(x, "cqf_3", "1");
    en->get_param(x, "cqf_2", b, sizeof b);
    CHECK(strcmp(a, b) && !strcmp(c, "0"), "the 0 unlatches it ('%s'), and the next 1 steps ('%s' to '%s')", c, a, b);
    en->set_param(x, "cqx_1", "1");   /* a list cell under a button prefix (cqx_1, ALL) doesn't latch */
    en->get_param(x, "cqx_1_on", c, sizeof c);
    CHECK(!strcmp(c, "0"), "a list cell under the prefix (cqx_1) never lights ('%s')", c);
    en->destroy(x);
}

/* 0.18 device bug: every image button acts once per touch (button_tap: two sets) as a single set of 1 does: an arrow steps one rhythm,
 * progression or voicing, a toggle toggles once; the fields whose second act was a no-op stay as they were (0.24.1 PHRASE's) */
static void test_18_buttons_act_once(void) {
    static const struct { void (*at)(AEffect *); const char *where, *keys[7]; } CASES[] = {
        {at_bar, "a bar open", {"cqf_1", "cqf_2", "cqf_3", NULL}},   /* 0.24 cst_ retired; 0.24.1 the RHYTHM page's cells too: PHRASE's */
        {at_rhythm, "RHYTHM, no bar open", {"cqf_1", "cqf_2", "cqf_3", NULL}},
        {at_copy, "COPY TO...", {"cqx_4", "cqx_6", "cqf_3", NULL}},
        {at_chords, "CHORDS", {"cpr_1", "cpr_2", "cpr_3", "cvo_1", "cvo_2", "cvo_3", NULL}},
        {at_chords, "CHORDS", {"kyb_1", NULL}},
        {at_prog, "PROGRESSIONS", {"cpr_1", "cpr_3", NULL}},
        {at_voice, "VOICING", {"cvo_1", "cvo_3", NULL}}};
    static char one_s[4096], two_s[4096];
    char b[64], c[64];
    int ok = 1, n = 0;
    for (size_t t = 0; t < sizeof CASES / sizeof CASES[0]; t++)
        for (int k = 0; k < 7 && CASES[t].keys[k]; k++, n++) {
            const char *key = CASES[t].keys[k];
            AEffect *one = VSTPluginMain(host), *two = VSTPluginMain(host);
            CASES[t].at(one);
            CASES[t].at(two);
            tap(one, key, 1);   /* one set of 1: the cell acts once */
            button_tap(two, key);
            screen_of(one, key, one_s, sizeof one_s);
            screen_of(two, key, two_s, sizeof two_s);
            if (strcmp(one_s, two_s)) printf("     %s, %s:\n       one set  %s\n       touched  %s\n", CASES[t].where, key, one_s, two_s), ok = 0;
            one->d(one, effClose, 0, 0, NULL, 0);
            two->d(two, effClose, 0, 0, NULL, 0);
        }
    CHECK(ok, "each of %d image-button touches (two sets) does what one set of 1 does", n);

    AEffect *e = VSTPluginMain(host);
    at_copy(e);
    button_tap(e, "cqx_4");
    display(e, "cqx_4", b);
    display(e, "rmsg", c);
    CHECK(!strcmp(b, "COPY: RHYTHM + CHORDS") && !strcmp(c, "COPY RHYTHM + CHORDS: its chord changes and octaves too") && !lit(e, "cqx_4"),
          "a touch on COPY toggles it once ('%s', '%s'; not lit: the label says it)", b, c);
    button_tap(e, "cqx_4");
    display(e, "cqx_4", b);
    display(e, "rmsg", c);
    CHECK(!strcmp(b, "COPY: RHYTHM ONLY") && !strcmp(c, "COPY RHYTHM ONLY: the hits alone"), "the next touch toggles it back ('%s', '%s')", b, c);
    e->d(e, effClose, 0, 0, NULL, 0);
    test_18_buttons_latch();
}

/* 0.18 (owner, on the Force): knobs 2-5 (k_s2..k_s5) are named for what they control, through the wrapper's effGetParamName
 * (dynamic_name), in CHORDS mode COLOUR..STRUM and in RHYTHM mode (RHYTHM, a bar open) SYNC..FILL; a mode change pushes an
 * UpdateDisplay, on which MPC reads the names again */
static void test_18_slot_names(void) {
    static const char *const CH[4] = {"Chords Colour", "Chords Inversion", "Chords Spread", "Chords Strum"};
    static const char *const RH[4] = {"Chords Sync", "Chords Ghosts", "Chords Humanize", "Chords Cadence"};   /* 0.24 PHRASE: knob 5 CADENCE */
    static const struct { const char *tap, *where; const char *const *want; } STEPS[] = {
        {NULL, "CHORDS", CH}, {"cvm_2", "RHYTHM", RH}, {"cjp_2", "a bar open", RH}, {"cqe_5", "RHYTHM after DONE", RH},
        {"cvm_1", "CHORDS again", CH}};   /* 0.24 the strip (cst_) and FIX (cvm_3) are retired: a bar opens from its JAM bar cell */
    char b[64], key[8];
    AEffect *e = VSTPluginMain(host);
    run(e, 8, 0);
    own_pages(e);
    for (size_t t = 0; t < sizeof STEPS / sizeof STEPS[0]; t++) {
        long was = redraws;
        int ok = 1;
        if (STEPS[t].tap) touch(e, STEPS[t].tap), run(e, 40, 0);
        b[0] = 0;
        for (int j = 0; j < 4; j++) {
            snprintf(key, sizeof key, "k_s%d", j + 2);
            char n[64] = "";
            e->d(e, effGetParamName, idx(key), 0, n, 0);
            ok &= !strcmp(n, STEPS[t].want[j]) && strlen(n) < 32;
            if (!j) strcpy(b, n);
        }
        CHECK(ok && (!STEPS[t].tap || redraws > was), "%s: knobs 2-5 named %s..%s (k_s2 '%s')%s", STEPS[t].where, STEPS[t].want[0],
              STEPS[t].want[3], b, STEPS[t].tap ? ", after an UpdateDisplay" : "");
    }
    e->d(e, effClose, 0, 0, NULL, 0);
}

/* the RHYTHM view's screen updates while playing: 16 bars (bars 1-4 four rhythms, repeated), 160 BPM, FOLLOW on; 0.24.1 the centre's
 * dots (cqzc_) for the retired step row */
static void test_18_screen_rate_rhythm(void) {
    char was[16 * 8], now[16 * 8], b[64], key[8];
    AEffect *e = VSTPluginMain(host);   /* INIT: 4 bars of Sustain, FOLLOW on */
    tap(e, "cvm_2", 1);
    for (int bar = 2; bar <= 4; bar++) {   /* bar n: the library's rhythm n-1 (Ballad, Half-time, Pulse) */
        snprintf(key, sizeof key, "cjp_%d", bar);   /* 0.24 the JAM bar cell (the strip, cst_, is retired) */
        tap(e, key, 1);
        for (int k = 1; k < bar; k++) tap(e, "cqf_3", 1);   /* 0.24.1 PHRASE's field and DONE (the RHYTHM page's are retired) */
        tap(e, "cqe_5", 1);
    }
    e->setP(e, idx("length"), 1.0f);   /* 16 bars: bars 5-16 repeat 1-4 */
    run(e, 8, 0);
    bpm = 160.0;
    ti[3] = 0;
    run(e, 44100 / 128, 1);
    pushes = 0;
    int n = 10 * 44100 / 128, changes = 0;
    was[0] = 0;
    for (int k = 0; k < n; k++) {
        run(e, 1, 1);
        now[0] = 0;
        for (int i = 1; i <= 16; i++) {
            snprintf(key, sizeof key, "cqzc_%d", i);
            display(e, key, b);
            strncat(now, b, 7);
            strcat(now, "|");
        }
        if (k && strcmp(now, was)) changes++;
        strcpy(was, now);
    }
    double rate = pushes * 44100.0 / (n * 128), bars = 10 * 160.0 / 60.0 / 4;
    CHECK(rate <= SCREEN_BUDGET, "RHYTHM view screen updates at 160 BPM, FOLLOW on: %.1f/s (budget %d)", rate, SCREEN_BUDGET);
    CHECK(changes >= 1 && changes <= (int)bars + 1, "the centre's dots change at most once a bar: %d changes in %.1f bars", changes, bars);
    run(e, 4, 0);
    bpm = 120.0;
    ti[3] = 0;
    e->d(e, effClose, 0, 0, NULL, 0);
}

/* the RHYTHM page's texts on the engine: knobs 2-5 ("user > effective" under COMPLEXITY, every text fits) and the browser (0.24.1 the
 * step row's marks, the action row, the strip's tags, COPY TO...'s cells and the field are retired) */
static void test_18_rhythm_texts(void) {
    static const char *const VC[6] = {"Power", "Triad", "7th", "9th", "11th", "13th"};
    const mpc_engine_t *en = mpc_engine();
    void *x = en->create(NULL);   /* INIT: C major Pop (C G Am F), Sustain */
    seq_t *q = x;
    char b[64], c[64], worst[64] = "";
    int over = 0, arrows = 0;
    eng_set(en, x, "length", 3);   /* 8 bars */
    for (int mode = 0; mode < 2; mode++) {
        en->set_param(x, mode ? "cvm_2" : "cvm_1", "1");
        for (int cx = 0; cx <= 100; cx += 25) {
            eng_set(en, x, "cx_1", cx);
            for (int j = 0; j < 4; j++)
                for (int v = 0; v < PARAMS[idx(KS18[j])].nopts; v++) {   /* in order: a fewer-step knob takes each of its steps */
                    eng_set(en, x, KS18[j], v);
                    eng_disp(en, x, KS18[j], b);
                    arrows += strstr(b, " > ") != NULL;
                    if (theory_text_width(b) > 14) over++, snprintf(worst, sizeof worst, "%s '%s'", KS18[j], b);
                }
            for (int j = 0; j < 4; j++) eng_set(en, x, KS18[j], j == 3 ? 0 : 1);   /* back down: one step a set */
            for (int j = 0; j < 4; j++) for (int k = 0; k < 4; k++) eng_set(en, x, KS18[j], 0);
        }
    }
    CHECK(!over && arrows > 20, "every slot text at every option and COMPLEXITY 0..100 in both modes fits 14 characters (%d over; %s), "
          "%d read 'user > effective'", over, worst, arrows);
    en->set_param(x, "cvm_1", "1");
    eng_set(en, x, "k_s2", 1);   /* Triad */
    eng_set(en, x, "cx_1", 100);
    eng_disp(en, x, "k_s2", b);
    snprintf(c, sizeof c, "Triad > %s", VC[seq_vknob_eff(q, VK_COL) + 1]);
    CHECK(!strcmp(b, c) && seq_vknob_eff(q, VK_COL) > 0, "CHORDS at COMPLEXITY 100: COLOUR '%s' (the user's, then what plays)", b);
    en->set_param(x, "cvm_2", "1");
    eng_set(en, x, "k_s2", 2);   /* SYNC as drawn */
    eng_set(en, x, "cx_1", 0);
    eng_disp(en, x, "k_s2", b);
    eng_disp(en, x, "cx_1", c);
    CHECK(!strcmp(b, "as drawn > -2") && !strcmp(c, "1 hit a bar"), "RHYTHM at COMPLEXITY 0: SYNC '%s', cx_1 '%s'", b, c);
    en->set_param(x, "style_1", "2");   /* Pulse in every bar */
    eng_set(en, x, "cx_1", 50);
    /* 0.24.1 the step row's marks, the action row (RESET KNOBS, LOCK), the strip's tags, COPY TO...'s cells and the field were the
     * RHYTHM page's cells, retired: PHRASE's do their jobs (test_24_phrase_cells). The browser, from PHRASE's field, with bar 3 locked */
    seq_rbar_open(q, LANE_CHORDS, 2), seq_rbar_lock(q, LANE_CHORDS), seq_rbar_done(q, LANE_CHORDS);
    en_press(en, x, "cqf_2");   /* the RHYTHMS browser, every unlocked bar */
    en->get_param(x, "btl", b, sizeof b);
    en->get_param(x, "rbt_4", c, sizeof c);
    en->get_param(x, "rbt_4_on", worst, sizeof worst);
    CHECK(seq_cview(q) == CVIEW_RBROWSE && !strcmp(b, "RHYTHMS" DOT "Pulse" DOT "every unlocked bar") && !strcmp(c, "Pulse" DOT "4 hits") &&
          !strcmp(worst, "1"), "the browser ('%s'): the Basic feel, Pulse's tile lit ('%s')", b, c);
    en->set_param(x, "rbt_1", "1");   /* Sustain: a try */
    en->set_param(x, "bcn_1", "1");
    en->get_param(x, "rmsg", b, sizeof b);
    CHECK(seq_bar_rhythm(q, LANE_CHORDS, 0, NULL) == 3 && !strcmp(b, "Cancelled: back as it was"), "a try, then CANCEL: back to Pulse ('%s')", b);
    en_press(en, x, "cqf_2");
    en->set_param(x, "rbg_5", "1");   /* Latin: its first rhythm */
    en->get_param(x, "rbf_1", c, sizeof c);
    en->set_param(x, "bdo_1", "1");
    en->get_param(x, "rmsg", b, sizeof b);
    snprintf(worst, sizeof worst, "Kept %s.", rhythm_name(16));
    CHECK(seq_bar_rhythm(q, LANE_CHORDS, 0, NULL) == 16 && seq_bar_rhythm(q, LANE_CHORDS, 3, NULL) == 16 && seq_bar_rhythm(q, LANE_CHORDS, 2, NULL) == 3 && !strcmp(b, worst) &&
          !strcmp(c, rhythm_feel(16)), "a feel chip tries its first rhythm in every unlocked bar (the locked one kept); DONE '%s'", b);
    en->destroy(x);
}

/* Ruling R26: every slot turn that moves its knob is reported back, so the wrapper's last report is what MPC holds and a mode change
 * re-reports each slot that differs: the next Q-Link turn goes on from the new mode's value, never from a stale one */
static void test_18_slot_rereport(void) {
    char b[64];
    AEffect *e = VSTPluginMain(host);   /* INIT */
    int s3 = idx("k_s3"), s4 = idx("k_s4");
    run(e, 40, 0);
    tap(e, "cvm_2", 1);
    run(e, TWO_POLLS, 0);
    e->setP(e, s4, 1 / 4.0f);   /* HUMANIZE late 4 ms */
    run(e, TWO_POLLS, 0);
    tap(e, "cvm_1", 1);         /* CHORDS: SPREAD Close, option 1 again */
    run(e, TWO_POLLS, 0);
    e->setP(e, s4, 2 / 4.0f);   /* MPC turns SPREAD to Open */
    run(e, TWO_POLLS, 0);
    CHECK(step_of_norm("k_s4", reported[s4]) == 2, "a 1:1 slot turn (SPREAD Open) is reported back (%d)", step_of_norm("k_s4", reported[s4]));
    long a0 = automated[s4];
    tap(e, "cvm_2", 1);         /* RHYTHM: HUMANIZE late 4 ms, option 1, the value reported before the turn */
    run(e, TWO_POLLS, 0);
    int rep = step_of_norm("k_s4", reported[s4]), held = automated[s4] > a0 ? rep : 2;   /* MPC holds its own turn unless told */
    CHECK(automated[s4] > a0 && rep == 1, "back on RHYTHM k_s4 is re-reported at HUMANIZE's option 1 (got %d)", rep);
    e->setP(e, s4, (held + 1) / 4.0f);   /* MPC turns on from the value it holds */
    run(e, TWO_POLLS, 0);
    display(e, "k_s4", b);
    CHECK(!strcmp(b, "late 8 ms"), "the next turn up is one step: '%s' (not late 12 ms)", b);
    /* a direction-mapped slot: INVERSION -1 and GHOSTS few both at option 1; CHORDS reports -1, MPC turns INVERSION to Root */
    tap(e, "cvm_1", 1);
    e->setP(e, s3, 1 / 5.0f);   /* INVERSION -1 */
    run(e, TWO_POLLS, 0);
    tap(e, "cvm_2", 1);
    e->setP(e, s3, 1 / 5.0f);   /* GHOSTS few */
    run(e, TWO_POLLS, 0);
    tap(e, "cvm_1", 1);
    run(e, TWO_POLLS, 0);
    e->setP(e, s3, 2 / 5.0f);   /* MPC: Root */
    run(e, TWO_POLLS, 0);
    a0 = automated[s3];
    tap(e, "cvm_2", 1);
    run(e, TWO_POLLS, 0);
    rep = step_of_norm("k_s3", reported[s3]), held = automated[s3] > a0 ? rep : 2;
    CHECK(automated[s3] > a0 && rep == 1, "GHOSTS few is re-reported at option 1 after INVERSION's turn (got %d)", rep);
    e->setP(e, s3, (held - 1) / 5.0f);   /* MPC turns down from the value it holds */
    run(e, TWO_POLLS, 0);
    display(e, "k_s3", b);
    CHECK(!strcmp(b, "none"), "and a turn down from it is a step down: '%s'", b);
    e->d(e, effClose, 0, 0, NULL, 0);
}

/* Ruling R32: a mode tap with a bar open keeps its paints (DONE) and their undo steps; UNDO steps them back */
static void test_18_mode_keeps_bar(void) {
    static const char *const MODE[2] = {"cvm_1", "cvm_4"};   /* 0.24 FIX (cvm_3) retired: JAM */
    const mpc_engine_t *en = mpc_engine();
    for (int m = 0; m < 2; m++) {
        void *x = en->create(NULL);   /* INIT: Sustain x--------------- */
        seq_t *q = x;
        unsigned char c[16];
        char pic[17];
        int n;
        en->set_param(x, "cvm_2", "1");
        n = q->undo_n;
        en->set_param(x, "cjp_2", "1");   /* bar 2 open (0.24 the JAM bar cell: the strip is retired) */
        en->set_param(x, "cqp_2", "1");   /* HIT on steps 5, 9 and 13 (0.24.1 PHRASE's paints and steps: the RHYTHM page's are retired) */
        en->set_param(x, "cqn_5", "1");
        en->set_param(x, "cqn_9", "1");
        en->set_param(x, "cqn_13", "1");
        if (m) en->set_param(x, "cqp_7", "1");   /* with COPY TO... open */
        en->set_param(x, MODE[m], "1");
        seq_bar_codes(q, LANE_CHORDS, 1, c);
        rhythm_format(c, pic);
        CHECK(seq_rbar_bar(q, LANE_CHORDS) < 0 && seq_cview(q) == (m ? CVIEW_JAM : CVIEW_CHORDS) && !strcmp(pic, "x---x---x---x---") && q->undo_n == n + 3,
              "%s with bar 2 open%s: the bar closes as DONE, its paints kept ('%s', %d undo steps)", MODE[m], m ? " (COPY TO...)" : "",
              pic, q->undo_n - n);
        en->set_param(x, "undo", "1");
        seq_bar_codes(q, LANE_CHORDS, 1, c);
        rhythm_format(c, pic);
        CHECK(!strcmp(pic, "x---x---x-------"), "UNDO steps the last paint back ('%s')", pic);
        en->set_param(x, "undo", "1");
        en->set_param(x, "undo", "1");
        seq_bar_codes(q, LANE_CHORDS, 1, c);
        rhythm_format(c, pic);
        CHECK(!strcmp(pic, "x---------------") && q->undo_n == n, "two more: the bar as before ('%s')", pic);
        en->destroy(x);
    }
}

/* COPY TO ALL that copies nothing and a RHYTHM field pick that changes nothing say why */
static void test_18_nothing_msgs(void) {
    const mpc_engine_t *en = mpc_engine();
    void *x = en->create(NULL);   /* INIT: Sustain, 4 bars */
    seq_t *q = x;
    char b[64], c[64], d[64], want[64];
    en->set_param(x, "cvm_2", "1");
    en->set_param(x, "length", "0");   /* 1 bar */
    en->set_param(x, "cjp_1", "1");   /* 0.24 bar 1 from its JAM bar cell (the strip is retired) */
    en->set_param(x, "cqp_6", "1");    /* COPY TO ALL (0.24.1 PHRASE's cells: the RHYTHM page's are retired) */
    en->get_param(x, "rmsg", b, sizeof b);
    CHECK(!strcmp(b, "No other bar in a 1-bar loop: nothing copied"), "COPY TO ALL in a 1-bar loop: '%s'", b);
    en->set_param(x, "cqe_4", "1");   /* CANCEL */
    en->set_param(x, "length", "2");   /* 4 bars, 2..4 locked */
    for (int bar = 1; bar < 4; bar++) seq_rbar_open(q, LANE_CHORDS, bar), seq_rbar_lock(q, LANE_CHORDS), seq_rbar_done(q, LANE_CHORDS);
    en->set_param(x, "cjp_1", "1");   /* 0.24 bar 1 from its JAM bar cell (the strip is retired) */
    en->set_param(x, "cqp_6", "1");
    en->get_param(x, "rmsg", b, sizeof b);
    en->set_param(x, "cqe_3", "1");    /* bar 1 locked too */
    en_press(en, x, "cqf_3");
    en->get_param(x, "rmsg", c, sizeof c);
    CHECK(!strcmp(b, "Every other bar is locked: nothing copied") && !strcmp(c, "Bar 1 is locked: nothing changed"),
          "the others locked: '%s'; > in a locked bar: '%s'", b, c);
    en->set_param(x, "cqe_5", "1");   /* DONE */
    en_press(en, x, "cqf_3");
    en->get_param(x, "rmsg", b, sizeof b);
    seq_rbar_open(q, LANE_CHORDS, 3), seq_rbar_lock(q, LANE_CHORDS), seq_rbar_done(q, LANE_CHORDS);   /* bar 4 unlocked, then given bar 1's next rhythm */
    en_press(en, x, "cqf_3");
    en_press(en, x, "cqf_3");
    en->get_param(x, "rmsg", d, sizeof d);
    snprintf(want, sizeof want, "Nothing changed: every unlocked bar has %s", rhythm_name(seq_bar_rhythm(q, LANE_CHORDS, 3, NULL)));
    CHECK(!strcmp(b, "Every bar is locked: nothing changed") && !strcmp(d, want) && seq_bar_rhythm(q, LANE_CHORDS, 0, NULL) == 0,
          "> with every bar locked: '%s'; with the unlocked bar on it already: '%s'", b, d);
    en->destroy(x);
}

