    test_221_update_display_per_bar();
    test_21_params_appended();
    test_21_slot_follows_mel_mode();
    test_21_jam_knob_texts();
    test_21_all_locked_text();
    test_21_gate_push_steps();
    test_21_kguard_new_slots();
